/** @typedef {import('./db.js').Db} Db */

import { Router } from 'express';
import { invalidBody, notFound } from './errors.js';
import {
  applyCellChanges,
  createWorkbook,
  getWorkbookSnapshot,
  getWorkbookRow,
  importWorksheetState,
  listWorkbooks,
  patchWorksheet,
  renameWorkbook,
  requireWorksheet,
  setSelection,
} from './store.js';
import { asObject, findValidationViolation, parseCellChanges, parseSelection } from './validate.js';

/**
 * The `/api` surface. Endpoints 1-6 of the shared contract (Issue #1, comment 1)
 * plus the selection endpoint and worksheet rename/activation used by the
 * editor shell.
 *
 * @param {Db} db
 * @returns {import('express').Router}
 */
export function createApiRouter(db) {
  const router = Router();

  // 1. Workbook list (home page).
  router.get('/workbooks', (_req, res) => {
    res.json(listWorkbooks(db));
  });

  // 2. Create a blank workbook (single active Sheet1, A1 selected).
  router.post('/workbooks', (req, res) => {
    const body = asObject(req.body ?? {});
    const rawName = body.name;
    if (rawName !== undefined && typeof rawName !== 'string') {
      throw invalidBody('Workbook name must be a string');
    }
    const name = /** @type {string} */ (rawName ?? 'Untitled spreadsheet').trim();
    if (!name) {
      res
        .status(400)
        .json({ error: { code: 'VALIDATION_ERROR', message: 'Workbook name cannot be empty' } });
      return;
    }
    res.status(201).json(createWorkbook(db, name));
  });

  // 3. Full editor snapshot.
  router.get('/workbooks/:id', (req, res) => {
    const snapshot = getWorkbookSnapshot(db, req.params.id);
    if (!snapshot) throw notFound('Workbook not found');
    res.json(snapshot);
  });

  // 4. Rename a workbook.
  router.patch('/workbooks/:id', (req, res) => {
    const body = asObject(req.body ?? {});
    res.json(renameWorkbook(db, req.params.id, body.name));
  });

  // 5. Bulk cell writes (cell edit and paste share this endpoint).
  router.put('/workbooks/:id/worksheets/:wid/cells', (req, res) => {
    const ws = requireWorksheet(db, req.params.id, req.params.wid);
    const changes = parseCellChanges(req.body);

    for (const change of changes) {
      if (change.row >= ws.row_count || change.col >= ws.col_count) {
        throw invalidBody(
          `Cell ${change.row},${change.col} is outside the worksheet structure (${ws.row_count}x${ws.col_count})`,
        );
      }
    }

    const violation = findValidationViolation(changes);
    if (violation) {
      res.status(409).json({ error: { code: violation.code, message: violation.message } });
      return;
    }

    res.json(applyCellChanges(db, ws, changes));
  });

  // 6. Whole-worksheet state import (undo/redo replay).
  router.put('/workbooks/:id/worksheets/:wid/state', (req, res) => {
    const ws = requireWorksheet(db, req.params.id, req.params.wid);
    const payload = asObject(req.body ?? {});
    const worksheet = importWorksheetState(db, ws, payload);
    const workbook = getWorkbookRow(db, ws.workbook_id);
    res.json({ updatedAt: workbook?.updated_at ?? new Date().toISOString(), worksheet });
  });

  // Selection persistence (contract §2.9): the last confirmed rectangle.
  router.put('/workbooks/:id/worksheets/:wid/selection', (req, res) => {
    const ws = requireWorksheet(db, req.params.id, req.params.wid);
    const selection = parseSelection(req.body);
    setSelection(db, ws, selection);
    res.json({ ok: true, selection });
  });

  // Worksheet rename / activation.
  router.patch('/workbooks/:id/worksheets/:wid', (req, res) => {
    const ws = requireWorksheet(db, req.params.id, req.params.wid);
    const body = asObject(req.body ?? {});
    res.json(patchWorksheet(db, ws, { name: body.name, isActive: body.isActive }));
  });

  return router;
}

/** @typedef {import('../../shared/types.js').CellChange} CellChange */
/** @typedef {import('../../shared/types.js').CellCoord} CellCoord */
/** @typedef {import('../../shared/types.js').CellEntry} CellEntry */
/** @typedef {import('../../shared/types.js').FilterSpec} FilterSpec */
/** @typedef {import('../../shared/types.js').PivotSpec} PivotSpec */
/** @typedef {import('../../shared/types.js').SelectionRect} SelectionRect */
/** @typedef {import('../../shared/types.js').ValidationRule} ValidationRule */
/** @typedef {import('../../shared/types.js').WorkbookSnapshot} WorkbookSnapshot */
/** @typedef {import('../../shared/types.js').WorkbookSummary} WorkbookSummary */
/** @typedef {import('../../shared/types.js').WorksheetSnapshot} WorksheetSnapshot */
/** @typedef {import('../../shared/types.js').WorksheetStatePayload} WorksheetStatePayload */
/** @typedef {import('./db.js').Db} Db */

import { DEFAULT_COL_COUNT, DEFAULT_ROW_COUNT, DEFAULT_SELECTION } from './config.js';
import { ApiError, invalidBody, notFound, validationError } from './errors.js';
import { newId, nowIso } from './ids.js';

/**
 * @typedef {object} WorkbookRow
 * @property {string} id
 * @property {string} name
 * @property {string} created_at
 * @property {string} updated_at
 */

/**
 * @typedef {object} WorksheetRow
 * @property {string} id
 * @property {string} workbook_id
 * @property {string} name
 * @property {number} position
 * @property {number} row_count
 * @property {number} col_count
 * @property {number} last_active
 * @property {string | null} last_selection
 */

/**
 * @template T
 * @param {string | null} raw
 * @param {T} fallback
 * @returns {T}
 */
function parseJson(raw, fallback) {
  if (raw === null || raw === undefined || raw === '') return fallback;
  try {
    return /** @type {T} */ (JSON.parse(raw));
  } catch {
    return fallback;
  }
}

/**
 * @param {Db} db
 * @returns {WorkbookSummary[]}
 */
export function listWorkbooks(db) {
  const rows = /** @type {{ id: string, name: string, updated_at: string }[]} */ (
    db
      .prepare('SELECT id, name, updated_at FROM workbooks ORDER BY updated_at DESC, created_at DESC')
      .all()
  );
  return rows.map((r) => ({ id: r.id, name: r.name, updatedAt: r.updated_at }));
}

/**
 * @param {Db} db
 * @param {string} id
 * @returns {WorkbookRow | null}
 */
export function getWorkbookRow(db, id) {
  const row = /** @type {WorkbookRow | undefined} */ (
    db.prepare('SELECT * FROM workbooks WHERE id = ?').get(id)
  );
  return row ?? null;
}

/**
 * @param {Db} db
 * @param {string} id
 * @returns {WorksheetRow | null}
 */
export function getWorksheetRow(db, id) {
  const row = /** @type {WorksheetRow | undefined} */ (
    db.prepare('SELECT * FROM worksheets WHERE id = ?').get(id)
  );
  return row ?? null;
}

/**
 * @param {Db} db
 * @param {string} workbookId
 * @param {string} worksheetId
 * @returns {WorksheetRow}
 */
export function requireWorksheet(db, workbookId, worksheetId) {
  const ws = getWorksheetRow(db, worksheetId);
  if (!ws || ws.workbook_id !== workbookId) {
    throw notFound('Worksheet not found');
  }
  return ws;
}

/**
 * @param {Db} db
 * @param {WorksheetRow} ws
 * @returns {WorksheetSnapshot}
 */
export function getWorksheetSnapshot(db, ws) {
  const cells = /** @type {{ row: number, col: number, raw: string }[]} */ (
    db
      .prepare('SELECT row, col, raw FROM cells WHERE worksheet_id = ? ORDER BY row, col')
      .all(ws.id)
  );
  const validations = /** @type {{ id: string, kind: string, range: string, params: string }[]} */ (
    db
      .prepare(
        'SELECT id, kind, range, params FROM validation_rules WHERE worksheet_id = ? ORDER BY rowid',
      )
      .all(ws.id)
  );
  const filters = /** @type {{ id: string, range: string, column_specs: string }[]} */ (
    db
      .prepare('SELECT id, range, column_specs FROM filters WHERE worksheet_id = ? ORDER BY rowid')
      .all(ws.id)
  );
  const pivots = /** @type {{
   *   id: string, source_worksheet_id: string, source_range: string, config: string,
   *   result_worksheet_id: string, last_result: string | null, stale: number
   * }[]} */ (
    db
      .prepare(
        `SELECT id, source_worksheet_id, source_range, config, result_worksheet_id, last_result, stale
         FROM pivots WHERE source_worksheet_id = ? ORDER BY rowid`,
      )
      .all(ws.id)
  );

  return {
    id: ws.id,
    name: ws.name,
    position: ws.position,
    isActive: ws.last_active === 1,
    rowCount: ws.row_count,
    colCount: ws.col_count,
    cells: /** @type {CellEntry[]} */ (cells.map((c) => [c.row, c.col, c.raw])),
    lastSelection: parseJson(ws.last_selection, /** @type {SelectionRect | null} */ (null)),
    validations: validations.map((v) => ({
      id: v.id,
      kind: /** @type {ValidationRule['kind']} */ (v.kind),
      range: v.range,
      params: parseJson(v.params, /** @type {Record<string, unknown>} */ ({})),
    })),
    filters: filters.map((f) => ({
      id: f.id,
      range: f.range,
      columnSpecs: parseJson(f.column_specs, /** @type {FilterSpec['columnSpecs']} */ ([])),
    })),
    pivots: pivots.map((p) => ({
      id: p.id,
      sourceWorksheetId: p.source_worksheet_id,
      sourceRange: p.source_range,
      config: parseJson(
        p.config,
        /** @type {PivotSpec['config']} */ ({
          rowField: null,
          columnField: null,
          valueField: null,
          summarize: 'SUM',
        }),
      ),
      resultWorksheetId: p.result_worksheet_id,
      lastResult: parseJson(p.last_result, /** @type {PivotSpec['lastResult']} */ (null)),
      stale: p.stale === 1,
    })),
  };
}

/**
 * @param {Db} db
 * @param {string} id
 * @returns {WorkbookSnapshot | null}
 */
export function getWorkbookSnapshot(db, id) {
  const wb = getWorkbookRow(db, id);
  if (!wb) return null;
  const worksheets = /** @type {WorksheetRow[]} */ (
    db.prepare('SELECT * FROM worksheets WHERE workbook_id = ? ORDER BY position, rowid').all(id)
  );
  return {
    id: wb.id,
    name: wb.name,
    updatedAt: wb.updated_at,
    worksheets: worksheets.map((ws) => getWorksheetSnapshot(db, ws)),
  };
}

/**
 * @param {Db} db
 * @param {string} workbookId
 * @param {string} [at]
 * @returns {string}
 */
export function touchWorkbook(db, workbookId, at = nowIso()) {
  db.prepare('UPDATE workbooks SET updated_at = ? WHERE id = ?').run(at, workbookId);
  return at;
}

/**
 * Create a blank workbook with a single active `Sheet1` and `A1` selected.
 *
 * @param {Db} db
 * @param {string} name
 * @returns {WorkbookSnapshot}
 */
export function createWorkbook(db, name) {
  const id = newId('wb');
  const worksheetId = newId('ws');
  const at = nowIso();
  db.transaction(() => {
    db.prepare('INSERT INTO workbooks (id, name, created_at, updated_at) VALUES (?, ?, ?, ?)').run(
      id,
      name,
      at,
      at,
    );
    db.prepare(
      `INSERT INTO worksheets (id, workbook_id, name, position, row_count, col_count, last_active, last_selection)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
    ).run(
      worksheetId,
      id,
      'Sheet1',
      0,
      DEFAULT_ROW_COUNT,
      DEFAULT_COL_COUNT,
      1,
      JSON.stringify(DEFAULT_SELECTION),
    );
  })();
  const snapshot = getWorkbookSnapshot(db, id);
  if (!snapshot) throw new Error('Failed to create workbook');
  return snapshot;
}

/**
 * @param {Db} db
 * @param {string} workbookId
 * @param {unknown} rawName
 * @returns {WorkbookSummary}
 */
export function renameWorkbook(db, workbookId, rawName) {
  const wb = getWorkbookRow(db, workbookId);
  if (!wb) throw notFound('Workbook not found');
  if (typeof rawName !== 'string') throw invalidBody('Workbook name must be a string');
  const name = rawName.trim();
  if (!name) throw validationError('Workbook name cannot be empty');
  const at = nowIso();
  db.transaction(() => {
    db.prepare('UPDATE workbooks SET name = ?, updated_at = ? WHERE id = ?').run(
      name,
      at,
      workbookId,
    );
  })();
  return { id: workbookId, name, updatedAt: at };
}

/**
 * @typedef {object} CellWriteResult
 * @property {string} updatedAt
 * @property {CellChange[]} changes
 * @property {CellCoord[]} removed
 */

/**
 * Apply a batch of cell writes atomically. `raw === ''` clears the cell.
 * All-or-nothing: validation must have rejected the batch before this runs.
 *
 * @param {Db} db
 * @param {WorksheetRow} ws
 * @param {CellChange[]} changes
 * @returns {CellWriteResult}
 */
export function applyCellChanges(db, ws, changes) {
  const at = nowIso();
  const upsert = db.prepare(
    `INSERT INTO cells (worksheet_id, row, col, raw) VALUES (?, ?, ?, ?)
     ON CONFLICT (worksheet_id, row, col) DO UPDATE SET raw = excluded.raw`,
  );
  const remove = db.prepare('DELETE FROM cells WHERE worksheet_id = ? AND row = ? AND col = ?');
  /** @type {CellChange[]} */
  const written = [];
  /** @type {CellCoord[]} */
  const removed = [];
  db.transaction(() => {
    for (const change of changes) {
      if (change.raw === '') {
        remove.run(ws.id, change.row, change.col);
        removed.push({ row: change.row, col: change.col });
      } else {
        upsert.run(ws.id, change.row, change.col, change.raw);
        written.push(change);
      }
    }
    touchWorkbook(db, ws.workbook_id, at);
  })();
  return { updatedAt: at, changes: written, removed };
}

/**
 * @param {Db} db
 * @param {string} workbookId
 * @param {string} worksheetId
 * @param {string} name
 * @returns {void}
 */
function assertWorksheetNameAvailable(db, workbookId, worksheetId, name) {
  const clash = /** @type {{ id: string } | undefined} */ (
    db
      .prepare('SELECT id FROM worksheets WHERE workbook_id = ? AND name = ? AND id <> ?')
      .get(workbookId, name, worksheetId)
  );
  if (clash) throw new ApiError(409, 'VALIDATION_ERROR', 'Worksheet name already exists');
}

/**
 * Rename and/or activate a worksheet. Never touches cell data.
 *
 * @param {Db} db
 * @param {WorksheetRow} ws
 * @param {{ name?: unknown, isActive?: unknown }} patch
 * @returns {{ worksheet: WorksheetSnapshot, updatedAt: string }}
 */
export function patchWorksheet(db, ws, patch) {
  /** @type {{ name?: string, isActive?: boolean }} */
  const fields = {};

  if (patch.name !== undefined) {
    if (typeof patch.name !== 'string') throw invalidBody('Worksheet name must be a string');
    const name = patch.name.trim();
    if (!name) throw validationError('Worksheet name cannot be empty');
    assertWorksheetNameAvailable(db, ws.workbook_id, ws.id, name);
    fields.name = name;
  }
  if (patch.isActive !== undefined) {
    if (typeof patch.isActive !== 'boolean') throw invalidBody('isActive must be a boolean');
    fields.isActive = patch.isActive;
  }
  if (fields.name === undefined && fields.isActive === undefined) {
    throw invalidBody('Nothing to update');
  }

  const at = nowIso();
  db.transaction(() => {
    if (fields.name !== undefined) {
      db.prepare('UPDATE worksheets SET name = ? WHERE id = ?').run(fields.name, ws.id);
    }
    if (fields.isActive !== undefined) {
      db.prepare('UPDATE worksheets SET last_active = 0 WHERE workbook_id = ?').run(ws.workbook_id);
      db.prepare('UPDATE worksheets SET last_active = ? WHERE id = ?').run(
        fields.isActive ? 1 : 0,
        ws.id,
      );
    }
    // Renaming is a visible workbook change; activating a tab is pure view
    // state and must not change "Last updated" (see PR #2 notes).
    if (fields.name !== undefined) touchWorkbook(db, ws.workbook_id, at);
  })();

  const updated = getWorksheetRow(db, ws.id);
  if (!updated) throw notFound('Worksheet not found');
  const workbook = getWorkbookRow(db, ws.workbook_id);
  return {
    worksheet: getWorksheetSnapshot(db, updated),
    updatedAt: fields.name !== undefined ? at : (workbook?.updated_at ?? at),
  };
}

/**
 * Persist the most recent confirmed selection rectangle (does not bump updated_at).
 *
 * @param {Db} db
 * @param {WorksheetRow} ws
 * @param {SelectionRect} selection
 * @returns {void}
 */
export function setSelection(db, ws, selection) {
  db.prepare('UPDATE worksheets SET last_selection = ? WHERE id = ?').run(
    JSON.stringify(selection),
    ws.id,
  );
}

/**
 * Replace the whole persisted state of one worksheet (undo/redo replay).
 * Runs in a single transaction: either the whole snapshot lands or nothing does.
 *
 * @param {Db} db
 * @param {WorksheetRow} ws
 * @param {WorksheetStatePayload} payload
 * @returns {WorksheetSnapshot}
 */
export function importWorksheetState(db, ws, payload) {
  const at = nowIso();
  db.transaction(() => {
    if (payload.name !== undefined) {
      if (typeof payload.name !== 'string') throw invalidBody('Worksheet name must be a string');
      const name = payload.name.trim();
      if (!name) throw validationError('Worksheet name cannot be empty');
      assertWorksheetNameAvailable(db, ws.workbook_id, ws.id, name);
      db.prepare('UPDATE worksheets SET name = ? WHERE id = ?').run(name, ws.id);
    }
    if (payload.rowCount !== undefined || payload.colCount !== undefined) {
      const rowCount = payload.rowCount ?? ws.row_count;
      const colCount = payload.colCount ?? ws.col_count;
      if (!Number.isInteger(rowCount) || rowCount < 1) {
        throw invalidBody('rowCount must be a positive integer');
      }
      if (!Number.isInteger(colCount) || colCount < 1) {
        throw invalidBody('colCount must be a positive integer');
      }
      db.prepare('UPDATE worksheets SET row_count = ?, col_count = ? WHERE id = ?').run(
        rowCount,
        colCount,
        ws.id,
      );
    }
    if (payload.cells !== undefined) {
      if (!Array.isArray(payload.cells)) throw invalidBody('cells must be an array');
      // The structure is the single fact source: a snapshot may not carry cells
      // the reported rowCount/colCount cannot show. Growing a worksheet is an
      // explicit structure operation (sub-issue B), never a side effect here.
      const structure = /** @type {{ row_count: number, col_count: number }} */ (
        db.prepare('SELECT row_count, col_count FROM worksheets WHERE id = ?').get(ws.id)
      );
      db.prepare('DELETE FROM cells WHERE worksheet_id = ?').run(ws.id);
      const insert = db.prepare(
        'INSERT INTO cells (worksheet_id, row, col, raw) VALUES (?, ?, ?, ?)',
      );
      for (const entry of payload.cells) {
        const [row, col, raw] = entry;
        if (!Number.isInteger(row) || row < 0 || !Number.isInteger(col) || col < 0) {
          throw invalidBody('Cell coordinates must be non-negative integers');
        }
        if (row >= structure.row_count || col >= structure.col_count) {
          throw invalidBody(
            `Cell ${row},${col} is outside the worksheet structure (${structure.row_count}x${structure.col_count})`,
          );
        }
        if (typeof raw !== 'string') throw invalidBody('Cell raw value must be a string');
        if (raw !== '') insert.run(ws.id, row, col, raw);
      }
    }
    if (payload.lastSelection !== undefined) {
      db.prepare('UPDATE worksheets SET last_selection = ? WHERE id = ?').run(
        payload.lastSelection === null ? null : JSON.stringify(payload.lastSelection),
        ws.id,
      );
    }
    if (payload.isActive !== undefined) {
      db.prepare('UPDATE worksheets SET last_active = 0 WHERE workbook_id = ?').run(ws.workbook_id);
      db.prepare('UPDATE worksheets SET last_active = ? WHERE id = ?').run(
        payload.isActive ? 1 : 0,
        ws.id,
      );
    }
    if (payload.validations !== undefined) {
      db.prepare('DELETE FROM validation_rules WHERE worksheet_id = ?').run(ws.id);
      const insert = db.prepare(
        'INSERT INTO validation_rules (id, worksheet_id, kind, range, params) VALUES (?, ?, ?, ?, ?)',
      );
      for (const rule of payload.validations) {
        insert.run(rule.id || newId('vr'), ws.id, rule.kind, rule.range, JSON.stringify(rule.params ?? {}));
      }
    }
    if (payload.filters !== undefined) {
      db.prepare('DELETE FROM filters WHERE worksheet_id = ?').run(ws.id);
      const insert = db.prepare(
        'INSERT INTO filters (id, worksheet_id, range, column_specs) VALUES (?, ?, ?, ?)',
      );
      for (const filter of payload.filters) {
        insert.run(
          filter.id || newId('flt'),
          ws.id,
          filter.range,
          JSON.stringify(filter.columnSpecs ?? []),
        );
      }
    }
    if (payload.pivots !== undefined) {
      db.prepare('DELETE FROM pivots WHERE source_worksheet_id = ?').run(ws.id);
      const insert = db.prepare(
        `INSERT INTO pivots (id, source_worksheet_id, source_range, config, result_worksheet_id, last_result, stale)
         VALUES (?, ?, ?, ?, ?, ?, ?)`,
      );
      for (const pivot of payload.pivots) {
        insert.run(
          pivot.id || newId('pvt'),
          ws.id,
          pivot.sourceRange,
          JSON.stringify(pivot.config),
          pivot.resultWorksheetId,
          pivot.lastResult === null || pivot.lastResult === undefined
            ? null
            : JSON.stringify(pivot.lastResult),
          pivot.stale ? 1 : 0,
        );
      }
    }
    touchWorkbook(db, ws.workbook_id, at);
  })();

  const updated = getWorksheetRow(db, ws.id);
  if (!updated) throw notFound('Worksheet not found');
  return getWorksheetSnapshot(db, updated);
}

/** @typedef {import('../../shared/types.js').CellChange} CellChange */
/** @typedef {import('../../shared/types.js').SelectionRect} SelectionRect */

import { invalidBody } from './errors.js';

/**
 * @param {unknown} value
 * @returns {Record<string, any>}
 */
export function asObject(value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) {
    throw invalidBody('Request body must be a JSON object');
  }
  return /** @type {Record<string, any>} */ (value);
}

/**
 * @param {unknown} value
 * @param {string} field
 * @returns {number}
 */
function asNonNegativeInt(value, field) {
  if (typeof value !== 'number' || !Number.isInteger(value) || value < 0) {
    throw invalidBody(`${field} must be a non-negative integer`);
  }
  return value;
}

/**
 * @param {unknown} body
 * @returns {CellChange[]}
 */
export function parseCellChanges(body) {
  const obj = asObject(body);
  const raw = obj.changes;
  if (!Array.isArray(raw) || raw.length === 0) {
    throw invalidBody('changes must be a non-empty array');
  }
  return raw.map((entry) => {
    const change = asObject(entry);
    const row = asNonNegativeInt(change.row, 'row');
    const col = asNonNegativeInt(change.col, 'col');
    if (typeof change.raw !== 'string') throw invalidBody('raw must be a string');
    return { row, col, raw: change.raw };
  });
}

/**
 * @param {unknown} body
 * @returns {SelectionRect}
 */
export function parseSelection(body) {
  const obj = asObject(body);
  const r1 = asNonNegativeInt(obj.r1, 'r1');
  const c1 = asNonNegativeInt(obj.c1, 'c1');
  const r2 = asNonNegativeInt(obj.r2, 'r2');
  const c2 = asNonNegativeInt(obj.c2, 'c2');
  const anchorRaw = obj.anchor === undefined ? { row: r1, col: c1 } : asObject(obj.anchor);
  const anchor = {
    row: asNonNegativeInt(anchorRaw.row, 'anchor.row'),
    col: asNonNegativeInt(anchorRaw.col, 'anchor.col'),
  };
  return {
    r1: Math.min(r1, r2),
    c1: Math.min(c1, c2),
    r2: Math.max(r1, r2),
    c2: Math.max(c1, c2),
    anchor,
  };
}

/**
 * Validation-rule gate for cell writes (Issue #1, contract §2.5).
 *
 * The base PR owns the all-or-nothing transaction and the `409` error shape;
 * the actual dropdown and number-range rules are wired in by sub-issue E.
 * Returning `null` means "no rule rejects this batch".
 *
 * @param {CellChange[]} _changes
 * @returns {{ code: string, message: string } | null}
 */
export function findValidationViolation(_changes) {
  return null;
}

/**
 * Repeatable schema migrations.
 *
 * Every migration is applied inside a transaction and recorded in
 * `schema_migrations`, so running them repeatedly is safe. All tables of the
 * data model decided in Issue #1 (contract comment #1) exist from the start so
 * that follow-up worksheet/cell work only adds behavior, not schema churn.
 *
 * @typedef {{ id: string, sql: string }} Migration
 */

/** @type {Migration[]} */
export const MIGRATIONS = [
  {
    id: '001_initial_schema',
    sql: `
      CREATE TABLE IF NOT EXISTS workbooks (
        id          TEXT PRIMARY KEY,
        name        TEXT NOT NULL,
        created_at  TEXT NOT NULL,
        updated_at  TEXT NOT NULL
      );

      CREATE TABLE IF NOT EXISTS worksheets (
        id             TEXT PRIMARY KEY,
        workbook_id    TEXT NOT NULL REFERENCES workbooks(id) ON DELETE CASCADE,
        name           TEXT NOT NULL,
        position       INTEGER NOT NULL,
        row_count      INTEGER NOT NULL,
        col_count      INTEGER NOT NULL,
        last_active    INTEGER NOT NULL DEFAULT 0,
        last_selection TEXT
      );

      CREATE INDEX IF NOT EXISTS idx_worksheets_workbook
        ON worksheets (workbook_id, position);

      CREATE TABLE IF NOT EXISTS cells (
        worksheet_id TEXT NOT NULL REFERENCES worksheets(id) ON DELETE CASCADE,
        row          INTEGER NOT NULL,
        col          INTEGER NOT NULL,
        raw          TEXT NOT NULL,
        PRIMARY KEY (worksheet_id, row, col)
      );

      CREATE TABLE IF NOT EXISTS validation_rules (
        id           TEXT PRIMARY KEY,
        worksheet_id TEXT NOT NULL REFERENCES worksheets(id) ON DELETE CASCADE,
        kind         TEXT NOT NULL,
        range        TEXT NOT NULL,
        params       TEXT NOT NULL
      );

      CREATE INDEX IF NOT EXISTS idx_validation_rules_worksheet
        ON validation_rules (worksheet_id);

      CREATE TABLE IF NOT EXISTS filters (
        id           TEXT PRIMARY KEY,
        worksheet_id TEXT NOT NULL REFERENCES worksheets(id) ON DELETE CASCADE,
        range        TEXT NOT NULL,
        column_specs TEXT NOT NULL
      );

      CREATE INDEX IF NOT EXISTS idx_filters_worksheet
        ON filters (worksheet_id);

      CREATE TABLE IF NOT EXISTS pivots (
        id                   TEXT PRIMARY KEY,
        source_worksheet_id  TEXT NOT NULL REFERENCES worksheets(id) ON DELETE CASCADE,
        source_range         TEXT NOT NULL,
        config               TEXT NOT NULL,
        result_worksheet_id  TEXT NOT NULL REFERENCES worksheets(id) ON DELETE CASCADE,
        last_result          TEXT,
        stale                INTEGER NOT NULL DEFAULT 0
      );

      CREATE INDEX IF NOT EXISTS idx_pivots_source_worksheet
        ON pivots (source_worksheet_id);

      CREATE INDEX IF NOT EXISTS idx_pivots_result_worksheet
        ON pivots (result_worksheet_id);
    `,
  },
];

import path from 'node:path';
import fs from 'node:fs';
import { fileURLToPath } from 'node:url';

/** `backend/` regardless of the current working directory. */
export const BACKEND_ROOT = fileURLToPath(new URL('..', import.meta.url));

/**
 * Structure of a freshly created (blank) worksheet: 6 rows x 26 columns (A-Z).
 *
 * The row count is a ratified shared-contract value: contract v1.1 (Issue #1
 * comment #12 item 6) set 9 rows and contract v1.2 (Issue #1 comment #15)
 * revised it to 6 after both sides' advisor reviews converged. Rationale:
 *
 * - The requirement package anchors every referenced coordinate at row <= 6
 *   (`A5:C6` is the lowest referenced range) and states no initial dimension, so
 *   both 6 and 9 satisfy the explicit requirements.
 * - Playwright's `getByRole(name)` matching is a case-insensitive substring
 *   match: with 10+ rows the coordinate `A1` is also matched by `A10`, `A100`,
 *   ... and any acceptance check locating a cell by its accessible name becomes
 *   ambiguous. Inserting a row is an explicit requirement (sub-issue B), and a
 *   harness whose reference implementation survives naive matching must keep
 *   "rows after the insertion" <= 9, i.e. start in [6, 9]. Starting at 6
 *   survives every such harness (headroom for 3 net insertions); starting at 9
 *   does not survive even one.
 * - 26 columns stays: `A-Z` is unambiguous up to 26 columns (`AA` only starts at
 *   27), so the preventive direction is free on the column axis while it costs
 *   on the row axis.
 *
 * Matching discipline (unchanged, Issue #1 comment #12): once structure
 * operations grow a worksheet past 9 rows (sub-issue B does that explicitly;
 * this layer never grows a worksheet by itself), acceptance scripts must locate
 * gridcells with `exact: true` or `[aria-label="A1"]`.
 *
 * `e2e/smoke.spec.ts` asserts both the naive-uniqueness invariant for every
 * coordinate of the referenced seed range and the exact structure totals
 * (6 rowheaders, 26 columnheaders), so drifting this constant either way breaks
 * a check instead of silently weakening acceptance.
 */
export const DEFAULT_ROW_COUNT = 6;
export const DEFAULT_COL_COUNT = 26;

/** Selection persisted for a worksheet with no selection history (A1). */
export const DEFAULT_SELECTION = Object.freeze({
  r1: 0,
  c1: 0,
  r2: 0,
  c2: 0,
  anchor: { row: 0, col: 0 },
});

/**
 * SQLite file location. Overridable with `DB_PATH` (exact file) or `DATA_DIR`
 * (directory); checks and tests point these at a throwaway directory so the
 * delivered application state is never modified by a self-check.
 *
 * @returns {string}
 */
export function resolveDbPath() {
  const explicit = process.env.DB_PATH?.trim();
  if (explicit) return path.resolve(explicit);
  const dataDir = process.env.DATA_DIR?.trim()
    ? path.resolve(process.env.DATA_DIR)
    : path.join(BACKEND_ROOT, 'data');
  return path.join(dataDir, 'app.db');
}

/**
 * @returns {{host: string, port: number}}
 */
export function resolveHostPort() {
  const host = process.env.HOST?.trim() || '0.0.0.0';
  const rawPort = process.env.PORT?.trim() || '3000';
  const port = Number.parseInt(rawPort, 10);
  if (!Number.isInteger(port) || port < 0 || port > 65535) {
    throw new Error(`Invalid PORT value: ${rawPort}`);
  }
  return { host, port };
}

/**
 * Locate the built frontend (`frontend/dist`). The backend serves it from the
 * same origin/PORT as `/api`. Returns `null` during backend-only development.
 *
 * @returns {string | null}
 */
export function resolveFrontendDist() {
  const candidates = [
    path.resolve(process.cwd(), 'frontend', 'dist'),
    path.resolve(process.cwd(), '..', 'frontend', 'dist'),
    path.join(BACKEND_ROOT, '..', 'frontend', 'dist'),
  ];
  for (const dir of candidates) {
    if (fs.existsSync(path.join(dir, 'index.html'))) return dir;
  }
  return null;
}

import { memo, useEffect, useRef, useState } from 'react';
import type { CellCoord, SelectionRect } from '../../../shared/types';
import { cellKey, columnLabel, toCoordinate } from '../lib/coordinates';
import { isSelected, normalizeSelection } from '../lib/selection';

export interface GridProps {
  rowCount: number;
  colCount: number;
  /** Sparse sheet content keyed by `cellKey`. */
  cells: Map<string, string>;
  selection: SelectionRect;
  editing: CellCoord | null;
  /** Called while dragging (persist=false) and once on mouseup (persist=true). */
  onSelectionChange: (selection: SelectionRect, persist: boolean) => void;
  onStartEdit: (coord: CellCoord) => void;
  onCommitEdit: (coord: CellCoord, raw: string) => void;
  onCancelEdit: () => void;
}

const CELL_WIDTH = 96;
const CELL_HEIGHT = 24;
const ROW_HEADER_WIDTH = 48;

/**
 * ARIA grid: `role="grid"`, accessible name "Worksheet grid",
 * `aria-multiselectable="true"`, every cell a `gridcell` whose accessible name
 * is its coordinate, and an exact `aria-selected` state for cells inside the
 * selected rectangle. The whole sheet is rendered (no viewport virtualization)
 * so that off-screen cells still expose `aria-selected="false"`.
 */
export function Grid(props: GridProps) {
  const {
    rowCount,
    colCount,
    cells,
    selection,
    editing,
    onSelectionChange,
    onStartEdit,
    onCommitEdit,
    onCancelEdit,
  } = props;

  const dragAnchor = useRef<CellCoord | null>(null);
  const [dragging, setDragging] = useState(false);
  const selectionRef = useRef(selection);
  selectionRef.current = selection;

  const cellFromEvent = (target: EventTarget | null): CellCoord | null => {
    if (!(target instanceof HTMLElement)) return null;
    const element = target.closest('[data-cell]');
    if (!(element instanceof HTMLElement)) return null;
    const row = Number(element.dataset.row);
    const col = Number(element.dataset.col);
    if (!Number.isInteger(row) || !Number.isInteger(col)) return null;
    return { row, col };
  };

  const handleMouseDown = (event: React.MouseEvent<HTMLDivElement>) => {
    if (event.button !== 0) return;
    const coord = cellFromEvent(event.target);
    if (!coord) return;
    // While an inline editor is open we must not preventDefault: the browser's
    // focus change is what commits the pending value (REQ-3-1-1).
    if (!editing) event.preventDefault();
    dragAnchor.current = coord;
    setDragging(true);
    onSelectionChange(normalizeSelection(coord, coord), false);
  };

  const handleMouseOver = (event: React.MouseEvent<HTMLDivElement>) => {
    if (!dragging) return;
    const anchor = dragAnchor.current;
    if (!anchor) return;
    const coord = cellFromEvent(event.target);
    if (!coord) return;
    onSelectionChange(normalizeSelection(anchor, coord), false);
  };

  const handleDoubleClick = (event: React.MouseEvent<HTMLDivElement>) => {
    const coord = cellFromEvent(event.target);
    if (!coord) return;
    onSelectionChange(normalizeSelection(coord, coord), true);
    onStartEdit(coord);
  };

  useEffect(() => {
    if (!dragging) return undefined;
    const handleMouseUp = () => {
      setDragging(false);
      dragAnchor.current = null;
      // Only the confirmed rectangle is written to the backend (contract §2.9).
      onSelectionChange(selectionRef.current, true);
    };
    window.addEventListener('mouseup', handleMouseUp);
    return () => window.removeEventListener('mouseup', handleMouseUp);
  }, [dragging, onSelectionChange]);

  return (
    <div className="h-full overflow-auto bg-white">
      <div
        role="grid"
        aria-label="Worksheet grid"
        aria-multiselectable="true"
        aria-rowcount={rowCount}
        aria-colcount={colCount}
        className="w-max select-none"
        onMouseDown={handleMouseDown}
        onMouseOver={handleMouseOver}
        onDoubleClick={handleDoubleClick}
      >
        <div role="row" className="flex">
          {/* Corner cell: kept out of the ARIA roles so that the 26 column
              headers map 1:1 to the columns and `columnheader` name lookups
              like "A" stay unambiguous. */}
          <div
            aria-hidden="true"
            className="sticky left-0 top-0 z-20 shrink-0 border-r-1 border-b-1 border-sheet-border bg-sheet-header"
            style={{ width: `${ROW_HEADER_WIDTH}px`, height: `${CELL_HEIGHT}px` }}
          />
          {Array.from({ length: colCount }, (_unused, col) => (
            <div
              key={col}
              role="columnheader"
              className="sticky top-0 z-10 flex shrink-0 items-center justify-center border-r-1 border-b-1 border-sheet-border bg-sheet-header text-xs text-sheet-header-text"
              style={{ width: `${CELL_WIDTH}px`, height: `${CELL_HEIGHT}px` }}
            >
              {columnLabel(col)}
            </div>
          ))}
        </div>

        {Array.from({ length: rowCount }, (_unused, row) => (
          <div key={row} role="row" className="flex">
            <div
              role="rowheader"
              aria-label={String(row + 1)}
              className="sticky left-0 z-10 flex shrink-0 items-center justify-center border-r-1 border-b-1 border-sheet-border bg-sheet-header text-xs text-sheet-header-text"
              style={{ width: `${ROW_HEADER_WIDTH}px`, height: `${CELL_HEIGHT}px` }}
            >
              {row + 1}
            </div>
            {Array.from({ length: colCount }, (_unusedCol, col) => {
              const isEditingCell = editing !== null && editing.row === row && editing.col === col;
              return (
                <GridCell
                  key={col}
                  row={row}
                  col={col}
                  raw={cells.get(cellKey(row, col)) ?? ''}
                  selected={isSelected(selection, row, col)}
                  editing={isEditingCell}
                  onCommitEdit={onCommitEdit}
                  onCancelEdit={onCancelEdit}
                />
              );
            })}
          </div>
        ))}
      </div>
    </div>
  );
}

interface GridCellProps {
  row: number;
  col: number;
  raw: string;
  selected: boolean;
  editing: boolean;
  onCommitEdit: (coord: CellCoord, raw: string) => void;
  onCancelEdit: () => void;
}

/**
 * One grid cell. Props are primitives plus stable callbacks so that changing
 * the selection re-renders only the cells whose `aria-selected` actually flips.
 */
const GridCell = memo(function GridCell(props: GridCellProps) {
  const { row, col, raw, selected, editing, onCommitEdit, onCancelEdit } = props;
  const coordinate = toCoordinate(row, col);

  return (
    <div
      role="gridcell"
      aria-label={coordinate}
      aria-selected={selected}
      data-cell=""
      data-row={row}
      data-col={col}
      className={
        'flex shrink-0 items-center border-r-1 border-b-1 border-sheet-border px-1 text-sm ' +
        (selected
          ? 'bg-sheet-accent-soft ring-2 ring-inset ring-sheet-accent'
          : 'bg-white text-sheet-text')
      }
      style={{ width: `${CELL_WIDTH}px`, height: `${CELL_HEIGHT}px` }}
    >
      {editing ? (
        <CellEditor
          coordinate={coordinate}
          initialValue={raw}
          onCommit={(value) => onCommitEdit({ row, col }, value)}
          onCancel={onCancelEdit}
        />
      ) : (
        <span className="truncate">{raw}</span>
      )}
    </div>
  );
});

interface CellEditorProps {
  coordinate: string;
  initialValue: string;
  onCommit: (value: string) => void;
  onCancel: () => void;
}

/** Inline editor exposed as text box "Edit <coordinate>" (contract §3). */
function CellEditor({ coordinate, initialValue, onCommit, onCancel }: CellEditorProps) {
  const [value, setValue] = useState(initialValue);
  const cancelled = useRef(false);
  const finished = useRef(false);

  const commitOnce = (next: string) => {
    if (finished.current) return;
    finished.current = true;
    onCommit(next);
  };

  return (
    <input
      autoFocus
      aria-label={`Edit ${coordinate}`}
      value={value}
      onChange={(event) => setValue(event.target.value)}
      onKeyDown={(event) => {
        event.stopPropagation();
        if (event.key === 'Enter') {
          event.preventDefault();
          commitOnce(value);
        } else if (event.key === 'Escape') {
          event.preventDefault();
          cancelled.current = true;
          finished.current = true;
          onCancel();
        }
      }}
      onBlur={() => {
        if (!cancelled.current) commitOnce(value);
      }}
      className="h-full w-full border-0 bg-white px-1 text-sm text-sheet-text outline-none"
    />
  );
}

/** Cell metrics shared with follow-up worksheet/structure work. */
export const GRID_METRICS = { CELL_WIDTH, CELL_HEIGHT, ROW_HEADER_WIDTH };

import type { WorksheetSnapshot } from '../../../shared/types';

export interface WorksheetTabsProps {
  worksheets: WorksheetSnapshot[];
  activeWorksheetId: string;
  onSelect: (worksheetId: string) => void;
}

/**
 * Bottom worksheet tab bar. Tabs use the ARIA `tab` role with an exact
 * `aria-selected` state driven by the persisted `last_active` flag. Adding,
 * renaming and deleting worksheets belongs to the worksheet sub-issue.
 */
export function WorksheetTabs({ worksheets, activeWorksheetId, onSelect }: WorksheetTabsProps) {
  return (
    <div
      role="tablist"
      aria-label="Worksheets"
      className="flex items-center gap-1 border-t-1 border-sheet-border bg-sheet-header px-2 py-1"
    >
      {worksheets.map((worksheet) => {
        const active = worksheet.id === activeWorksheetId;
        return (
          <button
            key={worksheet.id}
            type="button"
            role="tab"
            id={`worksheet-tab-${worksheet.id}`}
            aria-selected={active}
            aria-controls="worksheet-grid-panel"
            onClick={() => onSelect(worksheet.id)}
            className={
              'rounded-t px-3 py-1 text-sm ' +
              (active
                ? 'bg-white font-medium text-sheet-accent shadow-sm'
                : 'text-sheet-muted hover:bg-#e8eaed')
            }
          >
            {worksheet.name}
          </button>
        );
      })}
    </div>
  );
}

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { Link, useParams } from 'react-router-dom';
import type {
  CellChange,
  CellCoord,
  CellEntry,
  SelectionRect,
  WorkbookSnapshot,
  WorksheetSnapshot,
} from '../../../shared/types';
import { ApiClientError, api } from '../api/client';
import { cellKey, toCoordinate } from '../lib/coordinates';
import { lastUpdatedText } from '../lib/format';
import { A1_SELECTION, sameSelection } from '../lib/selection';
import { ErrorBanner } from './ErrorBanner';
import { FormulaBar } from './FormulaBar';
import { Grid } from './Grid';
import { WorksheetTabs } from './WorksheetTabs';

const LAST_UPDATED_LABEL_ID = 'workbook-last-updated';

function messageOf(error: unknown): string {
  if (error instanceof ApiClientError) return error.message;
  if (error instanceof Error) return error.message;
  return String(error);
}

/**
 * `/workbook/:id` editor shell: header, toolbar placeholder, name box +
 * formula bar, ARIA grid, worksheet tab bar. Cell edits and confirmed
 * selections are written through the contract endpoints and survive a refresh.
 */
export function WorkbookEditor() {
  const { id = '' } = useParams<{ id: string }>();
  const [snapshot, setSnapshot] = useState<WorkbookSnapshot | null>(null);
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState<string | null>(null);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [selectionByWorksheet, setSelectionByWorksheet] = useState<Record<string, SelectionRect>>(
    {},
  );
  const [editing, setEditing] = useState<CellCoord | null>(null);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setLoadError(null);
    api
      .getWorkbook(id)
      .then((loaded) => {
        if (cancelled) return;
        setSnapshot(loaded);
        setSelectionByWorksheet(
          Object.fromEntries(
            loaded.worksheets.map((worksheet) => [
              worksheet.id,
              worksheet.lastSelection ?? A1_SELECTION,
            ]),
          ),
        );
        setLoading(false);
      })
      .catch((error: unknown) => {
        if (cancelled) return;
        setLoadError(messageOf(error));
        setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [id]);

  const worksheets = snapshot?.worksheets ?? [];
  const activeWorksheet =
    worksheets.find((worksheet) => worksheet.isActive) ?? worksheets[0] ?? null;
  const activeWorksheetId = activeWorksheet?.id ?? '';
  const selection = selectionByWorksheet[activeWorksheetId] ?? A1_SELECTION;

  const cells = useMemo(() => {
    const map = new Map<string, string>();
    for (const [row, col, raw] of activeWorksheet?.cells ?? []) {
      map.set(cellKey(row, col), raw);
    }
    return map;
  }, [activeWorksheet]);

  // Refs keep the memoized grid callbacks stable while still reading the
  // latest worksheet/cell state.
  const activeWorksheetIdRef = useRef(activeWorksheetId);
  activeWorksheetIdRef.current = activeWorksheetId;
  const worksheetsRef = useRef<WorksheetSnapshot[]>(worksheets);
  worksheetsRef.current = worksheets;
  const cellsRef = useRef(cells);
  cellsRef.current = cells;

  const applyCellLocally = useCallback((worksheetId: string, changes: CellChange[]) => {
    setSnapshot((previous) => {
      if (!previous) return previous;
      return {
        ...previous,
        worksheets: previous.worksheets.map((worksheet) => {
          if (worksheet.id !== worksheetId) return worksheet;
          const map = new Map<string, string>();
          for (const [row, col, raw] of worksheet.cells) {
            map.set(cellKey(row, col), raw);
          }
          for (const change of changes) {
            const key = cellKey(change.row, change.col);
            if (change.raw === '') map.delete(key);
            else map.set(key, change.raw);
          }
          const cellsAfter: CellEntry[] = [...map.entries()].map(([key, raw]) => {
            const [row, col] = key.split(':').map(Number);
            return [row, col, raw];
          });
          return { ...worksheet, cells: cellsAfter };
        }),
      };
    });
  }, []);

  const commitCell = useCallback(
    async (coord: CellCoord, raw: string) => {
      setEditing(null);
      const worksheetId = activeWorksheetIdRef.current;
      if (!worksheetId) return;
      const key = cellKey(coord.row, coord.col);
      const previousValue = cellsRef.current.get(key) ?? '';
      if (previousValue === raw) return;

      applyCellLocally(worksheetId, [{ row: coord.row, col: coord.col, raw }]);
      try {
        const result = await api.putCells(id, worksheetId, [
          { row: coord.row, col: coord.col, raw },
        ]);
        setSnapshot((previous) => (previous ? { ...previous, updatedAt: result.updatedAt } : previous));
        setErrorMessage(null);
      } catch (error: unknown) {
        applyCellLocally(worksheetId, [{ row: coord.row, col: coord.col, raw: previousValue }]);
        setErrorMessage(messageOf(error));
      }
    },
    [id, applyCellLocally],
  );

  const handleSelectionChange = useCallback(
    (next: SelectionRect, persist: boolean) => {
      const worksheetId = activeWorksheetIdRef.current;
      if (!worksheetId) return;
      setSelectionByWorksheet((previous) => {
        const current = previous[worksheetId];
        if (current && sameSelection(current, next)) return previous;
        return { ...previous, [worksheetId]: next };
      });
      if (persist) {
        api.putSelection(id, worksheetId, next).catch((error: unknown) => {
          setErrorMessage(messageOf(error));
        });
      }
    },
    [id],
  );

  const handleSelectWorksheet = useCallback(
    async (worksheetId: string) => {
      setEditing(null);
      const target = worksheetsRef.current.find((worksheet) => worksheet.id === worksheetId);
      if (!target || target.isActive) return;
      const previousActiveId =
        worksheetsRef.current.find((worksheet) => worksheet.isActive)?.id ?? worksheetId;
      const markActive = (isActiveId: string) => {
        setSnapshot((previous) =>
          previous
            ? {
                ...previous,
                worksheets: previous.worksheets.map((worksheet) => ({
                  ...worksheet,
                  isActive: worksheet.id === isActiveId,
                })),
              }
            : previous,
        );
      };
      markActive(worksheetId);
      try {
        const result = await api.patchWorksheet(id, worksheetId, { isActive: true });
        markActive(worksheetId);
        setSnapshot((previous) =>
          previous ? { ...previous, updatedAt: result.updatedAt } : previous,
        );
        setErrorMessage(null);
      } catch (error: unknown) {
        markActive(previousActiveId);
        setErrorMessage(messageOf(error));
      }
    },
    [id],
  );

  const handleStartEdit = useCallback((coord: CellCoord) => {
    setEditing({ row: coord.row, col: coord.col });
  }, []);

  const handleCommitEdit = useCallback(
    (coord: CellCoord, raw: string) => {
      void commitCell(coord, raw);
    },
    [commitCell],
  );

  const handleCancelEdit = useCallback(() => {
    setEditing(null);
  }, []);

  if (loading) {
    return <div className="p-8 text-sm text-sheet-muted">Loading workbook…</div>;
  }

  if (loadError || !snapshot || !activeWorksheet) {
    return (
      <div className="mx-auto max-w-2xl p-8">
        <ErrorBanner message={loadError ?? 'Workbook not found'} />
        <Link to="/" className="text-sm text-sheet-accent underline">
          Back to workbooks
        </Link>
      </div>
    );
  }

  const anchorCell: CellCoord = { row: selection.r1, col: selection.c1 };
  const selectedRaw = cells.get(cellKey(anchorCell.row, anchorCell.col)) ?? '';

  return (
    <div className="flex h-screen flex-col bg-white">
      <header className="flex flex-wrap items-baseline gap-x-4 gap-y-1 border-b-1 border-sheet-border px-3 py-2">
        <h1 className="text-lg font-medium text-sheet-text">{snapshot.name}</h1>
        <p id={LAST_UPDATED_LABEL_ID} className="text-xs text-sheet-muted">
          {lastUpdatedText(snapshot.updatedAt)}
        </p>
      </header>

      {/* Toolbar placeholder: Undo/Redo/Data/Export land here in follow-up work. */}
      <div
        role="toolbar"
        aria-label="Toolbar"
        className="flex h-9 items-center gap-1 border-b-1 border-sheet-border bg-sheet-header px-2"
      />

      <FormulaBar
        coordinate={toCoordinate(anchorCell.row, anchorCell.col)}
        value={selectedRaw}
        onCommit={(value) => {
          void commitCell(anchorCell, value);
        }}
      />

      <ErrorBanner message={errorMessage} onDismiss={() => setErrorMessage(null)} />

      <div
        id="worksheet-grid-panel"
        role="tabpanel"
        aria-labelledby={`worksheet-tab-${activeWorksheetId}`}
        className="min-h-0 flex-1"
      >
        <Grid
          rowCount={activeWorksheet.rowCount}
          colCount={activeWorksheet.colCount}
          cells={cells}
          selection={selection}
          editing={editing}
          onSelectionChange={handleSelectionChange}
          onStartEdit={handleStartEdit}
          onCommitEdit={handleCommitEdit}
          onCancelEdit={handleCancelEdit}
        />
      </div>

      <WorksheetTabs
        worksheets={worksheets}
        activeWorksheetId={activeWorksheetId}
        onSelect={(worksheetId) => {
          void handleSelectWorksheet(worksheetId);
        }}
      />
    </div>
  );
}

import type { ApiErrorBody, CellChange, SelectionRect, WorkbookSnapshot, WorkbookSummary, WorksheetSnapshot } from '../../../shared/types';

/** Error carrying the HTTP status and the server-supplied `{error:{code,message}}`. */
export class ApiClientError extends Error {
  readonly status: number;
  readonly code: string;

  constructor(status: number, code: string, message: string) {
    super(message);
    this.name = 'ApiClientError';
    this.status = status;
    this.code = code;
  }
}

async function request<T>(path: string, init?: RequestInit): Promise<T> {
  let response: Response;
  try {
    response = await fetch(path, {
      headers: { 'Content-Type': 'application/json' },
      ...init,
    });
  } catch {
    throw new ApiClientError(0, 'NETWORK_ERROR', 'Could not reach the server. Please retry.');
  }

  const text = await response.text();
  let body: unknown = null;
  if (text) {
    try {
      body = JSON.parse(text);
    } catch {
      body = null;
    }
  }

  if (!response.ok) {
    const parsed = body as ApiErrorBody | null;
    throw new ApiClientError(
      response.status,
      parsed?.error?.code ?? 'ERROR',
      parsed?.error?.message ?? `Request failed with status ${response.status}`,
    );
  }
  return body as T;
}

export interface CellWriteResponse {
  updatedAt: string;
  changes: CellChange[];
  removed: { row: number; col: number }[];
}

export interface WorksheetPatchResponse {
  updatedAt: string;
  worksheet: WorksheetSnapshot;
}

function worksheetPath(workbookId: string, worksheetId: string): string {
  return `/api/workbooks/${encodeURIComponent(workbookId)}/worksheets/${encodeURIComponent(worksheetId)}`;
}

/** Same-origin `/api` client; the production build is served by the backend on the same PORT. */
export const api = {
  listWorkbooks(): Promise<WorkbookSummary[]> {
    return request<WorkbookSummary[]>('/api/workbooks');
  },
  getWorkbook(workbookId: string): Promise<WorkbookSnapshot> {
    return request<WorkbookSnapshot>(`/api/workbooks/${encodeURIComponent(workbookId)}`);
  },
  putCells(workbookId: string, worksheetId: string, changes: CellChange[]): Promise<CellWriteResponse> {
    return request<CellWriteResponse>(`${worksheetPath(workbookId, worksheetId)}/cells`, {
      method: 'PUT',
      body: JSON.stringify({ changes }),
    });
  },
  putSelection(
    workbookId: string,
    worksheetId: string,
    selection: SelectionRect,
  ): Promise<{ ok: true; selection: SelectionRect }> {
    return request<{ ok: true; selection: SelectionRect }>(
      `${worksheetPath(workbookId, worksheetId)}/selection`,
      { method: 'PUT', body: JSON.stringify(selection) },
    );
  },
  patchWorksheet(
    workbookId: string,
    worksheetId: string,
    patch: { name?: string; isActive?: boolean },
  ): Promise<WorksheetPatchResponse> {
    return request<WorksheetPatchResponse>(worksheetPath(workbookId, worksheetId), {
      method: 'PATCH',
      body: JSON.stringify(patch),
    });
  },
};

/**
 * Shared contract types between `frontend/` and `backend/`.
 *
 * This file is the single source of truth for the HTTP payload shapes and the
 * persisted data model described in Issue #1 (contract comment #1). Both sides
 * import it with `import type { ... } from '../../shared/types.js'`; it is a
 * declaration file, so it is erased at build time and creates no runtime or
 * package-linking dependency between the two applications.
 *
 * Conventions (fixed by the base PR, see PR #2):
 * - `row` and `col` are 0-based integers. Cell `A1` is `{row: 0, col: 0}`.
 * - Cell `raw` is the exact text the user submitted. Formulas are stored raw
 *   (starting with `=`); calculated results are never persisted.
 * - `updatedAt` / `createdAt` are ISO-8601 UTC strings and are the single
 *   source for the visible "Last updated: <value>" text.
 * - Errors always use the `ApiErrorBody` shape.
 * - Worksheet selection is persisted per worksheet as a full rectangle.
 */

/** A single cell address; 0-based. */
export interface CellCoord {
  row: number;
  col: number;
}

/** `[row, col, raw]`; the transport form of one persisted cell. */
export type CellEntry = [row: number, col: number, raw: string];

/** One requested cell write. `raw === ''` clears the cell. */
export interface CellChange {
  row: number;
  col: number;
  raw: string;
}

/**
 * The most recent successfully confirmed selection rectangle.
 * `r1/c1` is the top-left and `r2/c2` the bottom-right corner (normalized),
 * `anchor` is the cell the selection started from.
 */
export interface SelectionRect {
  r1: number;
  c1: number;
  r2: number;
  c2: number;
  anchor: CellCoord;
}

/** Home page list entry. */
export interface WorkbookSummary {
  id: string;
  name: string;
  updatedAt: string;
}

export type ValidationRuleKind = 'dropdown' | 'number';

export interface ValidationRule {
  id: string;
  kind: ValidationRuleKind;
  /** A1-style range expression, e.g. `B2:B10`. */
  range: string;
  params: Record<string, unknown>;
}

export type FilterCondition =
  | 'Text contains'
  | 'Greater than'
  | 'Before'
  | 'Is empty'
  | 'Is not empty';

export interface FilterColumnSpec {
  /** 0-based index relative to `range`'s first column. */
  columnIndex: number;
  type: 'values' | 'condition';
  /** For `type: 'values'`. */
  values?: string[];
  /** For `type: 'condition'`. */
  condition?: FilterCondition;
  value?: string;
}

export interface FilterSpec {
  id: string;
  /** A1-style range expression of the filtered region (header row included). */
  range: string;
  columnSpecs: FilterColumnSpec[];
}

export type PivotSummarize = 'SUM' | 'COUNT' | 'AVERAGE';

export interface PivotConfig {
  rowField: string | null;
  columnField: string | null;
  valueField: string | null;
  summarize: PivotSummarize;
}

export interface PivotResultSnapshot {
  cells: CellEntry[];
  rowCount: number;
  colCount: number;
}

export interface PivotSpec {
  id: string;
  sourceWorksheetId: string;
  /** A1-style source range (header row included). */
  sourceRange: string;
  config: PivotConfig;
  resultWorksheetId: string;
  lastResult: PivotResultSnapshot | null;
  stale: boolean;
}

export interface WorksheetSnapshot {
  id: string;
  name: string;
  position: number;
  isActive: boolean;
  rowCount: number;
  colCount: number;
  cells: CellEntry[];
  lastSelection: SelectionRect | null;
  validations: ValidationRule[];
  filters: FilterSpec[];
  pivots: PivotSpec[];
}

/** Full editor load payload (`GET /api/workbooks/:id`). */
export interface WorkbookSnapshot {
  id: string;
  name: string;
  updatedAt: string;
  worksheets: WorksheetSnapshot[];
}

/** Body of `PUT /api/workbooks/:id/worksheets/:wid/state` (undo/redo replay). */
export interface WorksheetStatePayload {
  name?: string;
  rowCount?: number;
  colCount?: number;
  cells?: CellEntry[];
  lastSelection?: SelectionRect | null;
  isActive?: boolean;
  validations?: ValidationRule[];
  filters?: FilterSpec[];
  pivots?: PivotSpec[];
}

export type ApiErrorCode =
  | 'NOT_FOUND'
  | 'VALIDATION_ERROR'
  | 'INVALID_BODY'
  | 'CONFLICT'
  | 'INTERNAL_ERROR';

/** Uniform error body for every `/api` failure. */
export interface ApiErrorBody {
  error: {
    code: ApiErrorCode | string;
    message: string;
  };
}

import { expect, test } from '@playwright/test';

/**
 * Base-PR smoke test and template for follow-up acceptance suites:
 * home page → open the seeded workbook → edit a cell → refresh → assert the
 * value persisted and the ARIA selection state is exact.
 */
test.describe('spreadsheet workspace smoke', () => {
  test('home page lists the seeded workbook', async ({ page }) => {
    await page.goto('/');
    await expect(page.getByRole('heading', { name: 'Workbooks' })).toBeVisible();
    const entry = page.getByRole('link', { name: 'Q3 Sales', exact: true });
    await expect(entry).toBeVisible();
    await expect(page.getByText('Last updated: ').first()).toBeVisible();
  });

  test('seeded coordinates are unambiguous accessible names', async ({ page }) => {
    // Playwright's `getByRole(name)` matching is a case-insensitive substring
    // match, so a spreadsheet that renders >= 10 rows makes `name: 'A1'`
    // ambiguous (A1 vs A10/A100...). The default worksheet structure (contract
    // v1.2 = Issue #1 comment #15: 6 x 26) is chosen so that every coordinate of
    // the referenced seed range `A1:C6` resolves to exactly one gridcell. This is
    // the regression guard for that invariant: growing the default structure past
    // 9 rows (or 26 columns) fails here, and the exact totals below fail on any
    // other drift too.
    await page.goto('/');
    await page.getByRole('link', { name: 'Q3 Sales', exact: true }).click();
    for (const column of ['A', 'B', 'C']) {
      for (const row of [1, 2, 3, 4, 5, 6]) {
        await expect(page.getByRole('gridcell', { name: `${column}${row}` })).toHaveCount(1);
      }
    }
    for (const row of [1, 2, 3, 4, 5, 6]) {
      await expect(page.getByRole('rowheader', { name: String(row) })).toHaveCount(1);
    }
    for (const column of ['A', 'B', 'C']) {
      await expect(page.getByRole('columnheader', { name: column })).toHaveCount(1);
    }
    // Exact structure totals: the default worksheet is exactly 6 rows x 26
    // columns, so the guard fails on drift in either direction.
    await expect(page.getByRole('rowheader')).toHaveCount(6);
    await expect(page.getByRole('columnheader')).toHaveCount(26);
  });

  test('grid, editing, refresh persistence and ARIA state', async ({ page }) => {
    await page.goto('/');
    await page.getByRole('link', { name: 'Q3 Sales', exact: true }).click();
    await expect(page).toHaveURL(/\/workbook\/.+/);

    const grid = page.getByRole('grid', { name: 'Worksheet grid' });
    await expect(grid).toBeVisible();
    await expect(grid).toHaveAttribute('aria-multiselectable', 'true');

    // Seeded content is rendered, including numbers and text.
    await expect(page.getByRole('gridcell', { name: 'A1', exact: true })).toHaveText('Region');
    await expect(page.getByRole('gridcell', { name: 'B2', exact: true })).toHaveText('1200');
    await expect(page.getByRole('gridcell', { name: 'C4', exact: true })).toHaveText('Open');
    // Empty seed cells still exist with an exact aria-selected state.
    await expect(page.getByRole('gridcell', { name: 'A5', exact: true })).toBeEmpty();
    await expect(page.getByRole('gridcell', { name: 'A5', exact: true })).toHaveAttribute(
      'aria-selected',
      'false',
    );

    // Worksheet tabs follow last_active.
    await expect(page.getByRole('tab', { name: 'Sheet1' })).toHaveAttribute('aria-selected', 'true');
    await expect(page.getByRole('tab', { name: 'Sheet2' })).toHaveAttribute('aria-selected', 'false');

    // Single-cell selection toggles aria-selected exactly.
    await expect(page.getByRole('gridcell', { name: 'A1', exact: true })).toHaveAttribute(
      'aria-selected',
      'true',
    );
    await page.getByRole('gridcell', { name: 'B2', exact: true }).click();
    await expect(page.getByRole('gridcell', { name: 'B2', exact: true })).toHaveAttribute(
      'aria-selected',
      'true',
    );
    await expect(page.getByRole('gridcell', { name: 'A1', exact: true })).toHaveAttribute(
      'aria-selected',
      'false',
    );

    // Formula bar mirrors the selected cell and writes back.
    const formulaBar = page.getByRole('textbox', { name: 'Formula bar' });
    await expect(formulaBar).toHaveValue('1200');

    // Inline editing: double click, type, Enter.
    await page.getByRole('gridcell', { name: 'B2', exact: true }).dblclick();
    const inlineEditor = page.getByRole('textbox', { name: 'Edit B2' });
    await inlineEditor.fill('1500');
    await inlineEditor.press('Enter');
    await expect(page.getByRole('gridcell', { name: 'B2', exact: true })).toHaveText('1500');
    await expect(formulaBar).toHaveValue('1500');

    // Escape cancels an uncommitted inline edit.
    await page.getByRole('gridcell', { name: 'C2', exact: true }).dblclick();
    const cancelEditor = page.getByRole('textbox', { name: 'Edit C2' });
    await cancelEditor.fill('discarded');
    await cancelEditor.press('Escape');
    await expect(page.getByRole('gridcell', { name: 'C2', exact: true })).toHaveText('Open');

    // Confirmed selection is persisted for the worksheet.
    await page.getByRole('gridcell', { name: 'A4', exact: true }).click();
    await expect(page.getByRole('gridcell', { name: 'A4', exact: true })).toHaveAttribute(
      'aria-selected',
      'true',
    );

    // Refresh: edited value and stored selection survive, seed rows are intact.
    await page.reload();
    await expect(page.getByRole('gridcell', { name: 'B2', exact: true })).toHaveText('1500');
    await expect(page.getByRole('gridcell', { name: 'A4', exact: true })).toHaveAttribute(
      'aria-selected',
      'true',
    );
    await expect(page.getByRole('gridcell', { name: 'A1', exact: true })).toHaveAttribute(
      'aria-selected',
      'false',
    );
    await expect(page.getByRole('gridcell', { name: 'A2', exact: true })).toHaveText('East');

    // Switching worksheets switches the grid and does not modify the source.
    await page.getByRole('tab', { name: 'Sheet2' }).click();
    await expect(page.getByRole('tab', { name: 'Sheet2' })).toHaveAttribute('aria-selected', 'true');
    await expect(page.getByRole('gridcell', { name: 'A1', exact: true })).toBeEmpty();
    await page.getByRole('tab', { name: 'Sheet1' }).click();
    await expect(page.getByRole('gridcell', { name: 'A1', exact: true })).toHaveText('Region');
    await expect(page.getByRole('gridcell', { name: 'A4', exact: true })).toHaveAttribute(
      'aria-selected',
      'true',
    );

    // The workbook is still listed on the home page.
    await page.goto('/');
    await expect(page.getByRole('link', { name: 'Q3 Sales', exact: true })).toBeVisible();
  });
});

/** @typedef {import('../../shared/types.js').CellEntry} CellEntry */
/** @typedef {import('./db.js').Db} Db */

import { DEFAULT_COL_COUNT, DEFAULT_ROW_COUNT, DEFAULT_SELECTION } from './config.js';
import { nowIso } from './ids.js';

/**
 * Idempotent evaluation seed (Issue #1, decision D2).
 *
 * Workbook `Q3 Sales` with `Sheet1` (A1:C4 filled, A5:C6 empty) and an empty
 * `Sheet2`. Seeding only fills gaps: an existing workbook/worksheet/cell is
 * never re-created or overwritten, so user edits and restarts are safe.
 */
export const SEED_WORKBOOK_ID = 'seed-q3-sales';
export const SEED_WORKBOOK_NAME = 'Q3 Sales';
export const SEED_SHEET1_ID = 'seed-q3-sales-sheet1';
export const SEED_SHEET2_ID = 'seed-q3-sales-sheet2';

/** @type {CellEntry[]} */
export const SEED_CELLS = [
  [0, 0, 'Region'],
  [0, 1, 'Sales'],
  [0, 2, 'Status'],
  [1, 0, 'East'],
  [1, 1, '1200'],
  [1, 2, 'Open'],
  [2, 0, 'North'],
  [2, 1, '800'],
  [2, 2, 'Closed'],
  [3, 0, 'South'],
  [3, 1, '700'],
  [3, 2, 'Open'],
];

/**
 * @param {Db} db
 * @returns {void}
 */
export function seedDatabase(db) {
  const at = nowIso();
  db.transaction(() => {
    const workbook = db.prepare('SELECT id FROM workbooks WHERE id = ?').get(SEED_WORKBOOK_ID);
    if (!workbook) {
      db.prepare('INSERT INTO workbooks (id, name, created_at, updated_at) VALUES (?, ?, ?, ?)').run(
        SEED_WORKBOOK_ID,
        SEED_WORKBOOK_NAME,
        at,
        at,
      );
    }

    ensureWorksheet(db, SEED_SHEET1_ID, 'Sheet1', 0, 1, SEED_CELLS);
    ensureWorksheet(db, SEED_SHEET2_ID, 'Sheet2', 1, 0, []);
  })();
}

/**
 * @param {Db} db
 * @param {string} id
 * @param {string} name
 * @param {number} position
 * @param {0 | 1} lastActive
 * @param {CellEntry[]} cells
 * @returns {void}
 */
function ensureWorksheet(db, id, name, position, lastActive, cells) {
  const existing = db.prepare('SELECT id FROM worksheets WHERE id = ?').get(id);
  if (existing) return; // never touch existing user data

  db.prepare(
    `INSERT INTO worksheets (id, workbook_id, name, position, row_count, col_count, last_active, last_selection)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
  ).run(
    id,
    SEED_WORKBOOK_ID,
    name,
    position,
    DEFAULT_ROW_COUNT,
    DEFAULT_COL_COUNT,
    lastActive,
    JSON.stringify(DEFAULT_SELECTION),
  );

  const insert = db.prepare('INSERT INTO cells (worksheet_id, row, col, raw) VALUES (?, ?, ?, ?)');
  for (const [row, col, raw] of cells) {
    insert.run(id, row, col, raw);
  }
}

/** @typedef {import('../../shared/types.js').ApiErrorBody} ApiErrorBody */
/** @typedef {import('../../shared/types.js').ApiErrorCode} ApiErrorCode */

/** Error carrying the HTTP status plus the uniform `{error:{code,message}}` body. */
export class ApiError extends Error {
  /**
   * @param {number} status
   * @param {ApiErrorCode | string} code
   * @param {string} message
   */
  constructor(status, code, message) {
    super(message);
    this.name = 'ApiError';
    this.status = status;
    this.code = code;
  }

  /** @returns {ApiErrorBody} */
  toBody() {
    return { error: { code: this.code, message: this.message } };
  }
}

/**
 * @param {string} message
 * @returns {ApiError}
 */
export function notFound(message) {
  return new ApiError(404, 'NOT_FOUND', message);
}

/**
 * @param {string} message
 * @returns {ApiError}
 */
export function invalidBody(message) {
  return new ApiError(400, 'INVALID_BODY', message);
}

/**
 * @param {string} message
 * @returns {ApiError}
 */
export function validationError(message) {
  return new ApiError(400, 'VALIDATION_ERROR', message);
}

