/** @typedef {import('./db.js').Db} Db */
/** @typedef {import('../../shared/types.js').ApiErrorBody} ApiErrorBody */

import fs from 'node:fs';
import path from 'node:path';
import express from 'express';
import { ApiError } from './errors.js';
import { createApiRouter } from './routes.js';

/**
 * @typedef {object} AppOptions
 * @property {string | null} [frontendDist] Absolute path of `frontend/dist`, or null for API-only development.
 */

/**
 * @param {Db} db
 * @param {AppOptions} [options]
 * @returns {import('express').Express}
 */
export function createApp(db, options = {}) {
  const app = express();
  app.disable('x-powered-by');
  app.use(express.json({ limit: '10mb' }));

  app.get('/api/health', (_req, res) => {
    res.json({ ok: true });
  });

  app.use('/api', createApiRouter(db));

  // Unknown API routes must still answer with the uniform error body.
  app.use('/api', (_req, res) => {
    res.status(404).json({ error: { code: 'NOT_FOUND', message: 'API route not found' } });
  });

  const dist = options.frontendDist ?? null;
  if (dist) {
    app.use(express.static(dist, { index: false }));
    // SPA fallback: `/workbook/:id` must survive a hard refresh / direct visit.
    app.use((req, res, next) => {
      if (req.method !== 'GET' && req.method !== 'HEAD') return next();
      if (!req.accepts('html')) return next();
      const indexFile = path.join(dist, 'index.html');
      if (!fs.existsSync(indexFile)) return next();
      // `send` rejects absolute paths that contain a dot-directory (e.g. a
      // checkout under `.factory26`), so resolve against the static root.
      res.sendFile('index.html', { root: dist }, (error) => {
        if (error) next(error);
      });
    });
  } else {
    app.get('/', (_req, res) => {
      res
        .status(503)
        .type('html')
        .send(
          '<!doctype html><meta charset="utf-8"><title>Frontend not built</title>' +
            '<p>frontend/dist is missing. Run <code>npm run build</code> in <code>frontend/</code> ' +
            'or use the Vite dev server on the frontend port.</p>',
        );
    });
  }

  app.use(
    /**
     * @param {unknown} err
     * @param {import('express').Request} _req
     * @param {import('express').Response} res
     * @param {import('express').NextFunction} _next
     */
    (err, _req, res, _next) => {
      if (res.headersSent) return;
      const status = err instanceof ApiError ? err.status : statusOf(err);
      res.status(status).json(toErrorBody(err));
    },
  );

  return app;
}

/**
 * @param {unknown} err
 * @returns {number}
 */
function statusOf(err) {
  const withStatus = /** @type {{ status?: unknown, statusCode?: unknown } | null} */ (err);
  const status = withStatus?.status ?? withStatus?.statusCode;
  return typeof status === 'number' ? status : 500;
}

/**
 * @param {unknown} err
 * @returns {ApiErrorBody}
 */
function toErrorBody(err) {
  if (err instanceof ApiError) return err.toBody();
  const typed = /** @type {{ type?: string, message?: string } | null} */ (err);
  if (typed?.type === 'entity.parse.failed') {
    return { error: { code: 'INVALID_BODY', message: 'Request body is not valid JSON' } };
  }
  if (typed?.type === 'entity.too.large') {
    return { error: { code: 'INVALID_BODY', message: 'Request body is too large' } };
  }
  const status = statusOf(err);
  if (status >= 400 && status < 500) {
    return { error: { code: 'INVALID_BODY', message: typed?.message ?? 'Invalid request' } };
  }
  return { error: { code: 'INTERNAL_ERROR', message: 'Unexpected server error' } };
}

