/** A1-style coordinate helpers. Rows and columns are 0-based everywhere. */

/**
 * Column index to spreadsheet label: 0 -> "A", 25 -> "Z", 26 -> "AA".
 */
export function columnLabel(col: number): string {
  let value = col + 1;
  let label = '';
  while (value > 0) {
    const remainder = (value - 1) % 26;
    label = String.fromCharCode(65 + remainder) + label;
    value = Math.floor((value - 1) / 26);
  }
  return label;
}

/** `(0, 0)` -> `"A1"`; this is the accessible name of every grid cell. */
export function toCoordinate(row: number, col: number): string {
  return `${columnLabel(col)}${row + 1}`;
}

/** Stable map key for sparse cell storage. */
export function cellKey(row: number, col: number): string {
  return `${row}:${col}`;
}

/** `"B3"` -> `{row: 2, col: 1}`, or null when the reference is malformed. */
export function parseCoordinate(reference: string): { row: number; col: number } | null {
  const match = /^([A-Za-z]+)([1-9][0-9]*)$/.exec(reference.trim());
  if (!match) return null;
  const letters = match[1].toUpperCase();
  let col = 0;
  for (const character of letters) {
    col = col * 26 + (character.charCodeAt(0) - 64);
  }
  return { row: Number.parseInt(match[2], 10) - 1, col: col - 1 };
}

import type { CellCoord, SelectionRect } from '../../../shared/types';

/** Default selection: `A1`, used for worksheets with no selection history. */
export const A1_SELECTION: SelectionRect = {
  r1: 0,
  c1: 0,
  r2: 0,
  c2: 0,
  anchor: { row: 0, col: 0 },
};

/** Build a normalized rectangle from its anchor and focus cells. */
export function normalizeSelection(anchor: CellCoord, focus: CellCoord): SelectionRect {
  return {
    r1: Math.min(anchor.row, focus.row),
    c1: Math.min(anchor.col, focus.col),
    r2: Math.max(anchor.row, focus.row),
    c2: Math.max(anchor.col, focus.col),
    anchor: { row: anchor.row, col: anchor.col },
  };
}

/** True when the cell is inside the selected rectangle (inclusive). */
export function isSelected(selection: SelectionRect, row: number, col: number): boolean {
  return row >= selection.r1 && row <= selection.r2 && col >= selection.c1 && col <= selection.c2;
}

/** Number of cells covered by the rectangle. */
export function selectionSize(selection: SelectionRect): number {
  return (selection.r2 - selection.r1 + 1) * (selection.c2 - selection.c1 + 1);
}

/** True when both rectangles describe the same region (anchor included). */
export function sameSelection(a: SelectionRect, b: SelectionRect): boolean {
  return (
    a.r1 === b.r1 &&
    a.c1 === b.c1 &&
    a.r2 === b.r2 &&
    a.c2 === b.c2 &&
    a.anchor.row === b.anchor.row &&
    a.anchor.col === b.anchor.col
  );
}

import { useEffect, useState } from 'react';

export interface FormulaBarProps {
  /** A1-style coordinate of the selected cell. */
  coordinate: string;
  /** Raw content of the selected cell (formula text stays raw). */
  value: string;
  onCommit: (value: string) => void;
}

/**
 * Name box + formula bar. The text box is labelled exactly "Formula bar"
 * (contract §3) and stays in two-way sync with the selected cell: committing
 * here writes through the same cells endpoint the grid uses.
 */
export function FormulaBar({ coordinate, value, onCommit }: FormulaBarProps) {
  const [draft, setDraft] = useState(value);

  useEffect(() => {
    setDraft(value);
  }, [value, coordinate]);

  const commit = () => {
    if (draft !== value) onCommit(draft);
  };

  return (
    <div className="flex items-stretch border-b-1 border-sheet-border bg-white">
      <input
        readOnly
        aria-label="Name box"
        value={coordinate}
        className="w-24 shrink-0 border-r-1 border-sheet-border bg-white px-2 py-1 text-center text-sm text-sheet-text outline-none"
      />
      <div className="flex w-8 shrink-0 items-center justify-center border-r-1 border-sheet-border text-sm italic text-sheet-muted">
        fx
      </div>
      <input
        aria-label="Formula bar"
        value={draft}
        onChange={(event) => setDraft(event.target.value)}
        onKeyDown={(event) => {
          if (event.key === 'Enter') {
            event.preventDefault();
            commit();
          } else if (event.key === 'Escape') {
            event.preventDefault();
            setDraft(value);
          }
        }}
        onBlur={commit}
        className="h-8 w-full min-w-0 flex-1 px-2 text-sm text-sheet-text outline-none"
      />
    </div>
  );
}

import fs from 'node:fs';
import path from 'node:path';
import Database from 'better-sqlite3';
import { MIGRATIONS } from './migrations.js';
import { nowIso } from './ids.js';

/** @typedef {import('better-sqlite3').Database} Db */

/**
 * Open (creating if needed) the SQLite database and bring the schema up to date.
 *
 * @param {string} dbPath
 * @returns {Db}
 */
export function openDatabase(dbPath) {
  if (dbPath !== ':memory:') {
    fs.mkdirSync(path.dirname(dbPath), { recursive: true });
  }
  const db = new Database(dbPath);
  db.pragma('journal_mode = WAL');
  db.pragma('foreign_keys = ON');
  db.pragma('busy_timeout = 5000');
  migrate(db);
  return db;
}

/**
 * Apply pending migrations. Safe to call on every start.
 *
 * @param {Db} db
 * @returns {void}
 */
export function migrate(db) {
  db.exec(`
    CREATE TABLE IF NOT EXISTS schema_migrations (
      id         TEXT PRIMARY KEY,
      applied_at TEXT NOT NULL
    );
  `);
  const rows = /** @type {{ id: string }[]} */ (
    db.prepare('SELECT id FROM schema_migrations').all()
  );
  const applied = new Set(rows.map((r) => r.id));
  const record = db.prepare('INSERT INTO schema_migrations (id, applied_at) VALUES (?, ?)');
  for (const migration of MIGRATIONS) {
    if (applied.has(migration.id)) continue;
    db.transaction(() => {
      db.exec(migration.sql);
      record.run(migration.id, nowIso());
    })();
  }
}

