import { useState } from 'react';
import { describe, expect, it, vi } from 'vitest';
import { fireEvent, render, screen } from '@testing-library/react';
import { Grid } from './Grid';
import type { GridProps } from './Grid';
import type { CellCoord, SelectionRect } from '../../../shared/types';
import { A1_SELECTION, normalizeSelection } from '../lib/selection';

const CELLS = new Map([
  ['0:0', 'Region'],
  ['1:1', '800'],
]);

function renderGrid(overrides: Partial<GridProps> = {}) {
  const props: GridProps = {
    rowCount: 2,
    colCount: 3,
    cells: CELLS,
    selection: A1_SELECTION,
    editing: null,
    onSelectionChange: vi.fn(),
    onStartEdit: vi.fn(),
    onCommitEdit: vi.fn(),
    onCancelEdit: vi.fn(),
    ...overrides,
  };
  render(<Grid {...props} />);
  return props;
}

/**
 * The grid is a controlled component: selection and inline editing live in the
 * editor. Interaction tests therefore use a small stateful harness, exactly
 * like `WorkbookEditor` wires it.
 */
interface HarnessSpies {
  onSelectionChange: (selection: SelectionRect, persist: boolean) => void;
  onCommitEdit: (coord: CellCoord, raw: string) => void;
  onCancelEdit: () => void;
}

function Harness(spies: HarnessSpies) {
  const [selection, setSelection] = useState<SelectionRect>(A1_SELECTION);
  const [editing, setEditing] = useState<CellCoord | null>(null);
  return (
    <Grid
      rowCount={2}
      colCount={3}
      cells={CELLS}
      selection={selection}
      editing={editing}
      onSelectionChange={(next, persist) => {
        setSelection(next);
        spies.onSelectionChange(next, persist);
      }}
      onStartEdit={(coord) => setEditing(coord)}
      onCommitEdit={(coord, raw) => {
        setEditing(null);
        spies.onCommitEdit(coord, raw);
      }}
      onCancelEdit={() => {
        setEditing(null);
        spies.onCancelEdit();
      }}
    />
  );
}

function renderHarness() {
  const spies: HarnessSpies = {
    onSelectionChange: vi.fn(),
    onCommitEdit: vi.fn(),
    onCancelEdit: vi.fn(),
  };
  render(<Harness {...spies} />);
  return spies;
}

describe('Grid ARIA contract', () => {
  it('exposes the grid, its accessible name and multiselectability', () => {
    renderGrid();
    const grid = screen.getByRole('grid', { name: 'Worksheet grid' });
    expect(grid.getAttribute('aria-multiselectable')).toBe('true');
  });

  it('names every cell by its coordinate and keeps aria-selected exact', () => {
    renderGrid();
    expect(screen.getByRole('gridcell', { name: 'A1' }).textContent).toBe('Region');
    expect(screen.getByRole('gridcell', { name: 'B2' }).textContent).toBe('800');
    expect(screen.getByRole('gridcell', { name: 'A1' }).getAttribute('aria-selected')).toBe('true');
    for (const coordinate of ['B1', 'C1', 'A2', 'B2', 'C2']) {
      expect(screen.getByRole('gridcell', { name: coordinate }).getAttribute('aria-selected')).toBe(
        'false',
      );
    }
  });

  it('marks exactly the cells of a rectangular selection', () => {
    renderGrid({ selection: normalizeSelection({ row: 0, col: 0 }, { row: 1, col: 2 }) });
    const selected = screen
      .getAllByRole('gridcell')
      .filter((cell) => cell.getAttribute('aria-selected') === 'true');
    expect(selected).toHaveLength(6);
  });

  it('provides row and column headers with accessible names', () => {
    renderGrid();
    expect(screen.getByRole('rowheader', { name: '1' }).textContent).toBe('1');
    expect(screen.getByRole('rowheader', { name: '2' }).textContent).toBe('2');
    expect(screen.getByRole('columnheader', { name: 'A' })).toBeTruthy();
    expect(screen.getByRole('columnheader', { name: 'C' })).toBeTruthy();
  });
});

describe('Grid interaction', () => {
  it('moves the aria-selected state to the clicked cell', () => {
    renderHarness();
    fireEvent.mouseDown(screen.getByRole('gridcell', { name: 'B2' }));
    fireEvent.mouseUp(window);
    expect(screen.getByRole('gridcell', { name: 'B2' }).getAttribute('aria-selected')).toBe('true');
    expect(screen.getByRole('gridcell', { name: 'A1' }).getAttribute('aria-selected')).toBe('false');
  });

  it('starts inline editing on double click and commits on Enter', () => {
    const spies = renderHarness();
    fireEvent.doubleClick(screen.getByRole('gridcell', { name: 'B1' }));
    const input = screen.getByRole('textbox', { name: 'Edit B1' }) as HTMLInputElement;
    fireEvent.change(input, { target: { value: '42' } });
    fireEvent.keyDown(input, { key: 'Enter' });
    expect(spies.onCommitEdit).toHaveBeenCalledTimes(1);
    expect(spies.onCommitEdit).toHaveBeenCalledWith({ row: 0, col: 1 }, '42');
  });

  it('cancels inline editing on Escape without committing', () => {
    const spies = renderHarness();
    fireEvent.doubleClick(screen.getByRole('gridcell', { name: 'B1' }));
    const input = screen.getByRole('textbox', { name: 'Edit B1' });
    fireEvent.change(input, { target: { value: 'ignored' } });
    fireEvent.keyDown(input, { key: 'Escape' });
    expect(spies.onCancelEdit).toHaveBeenCalledTimes(1);
    expect(spies.onCommitEdit).not.toHaveBeenCalled();
  });

  it('writes the rectangle only when the drag finishes', () => {
    const spies = renderHarness();
    fireEvent.mouseDown(screen.getByRole('gridcell', { name: 'A1' }));
    fireEvent.mouseOver(screen.getByRole('gridcell', { name: 'B2' }));
    expect(spies.onSelectionChange).toHaveBeenLastCalledWith(
      { r1: 0, c1: 0, r2: 1, c2: 1, anchor: { row: 0, col: 0 } },
      false,
    );
    fireEvent.mouseUp(window);
    expect(spies.onSelectionChange).toHaveBeenLastCalledWith(
      { r1: 0, c1: 0, r2: 1, c2: 1, anchor: { row: 0, col: 0 } },
      true,
    );
    // The intermediate drag steps never persist.
    const persisted = (spies.onSelectionChange as ReturnType<typeof vi.fn>).mock.calls.map(
      ([, persist]) => persist,
    );
    expect(persisted).toEqual([false, false, true]);
  });
});

