/**
 * Defensive total-structure caps (Issue #4 comment #35 D-B1; requirement left
 * the upper bound open). The grid renders every cell without virtualization,
 * so an unbounded `count` could make every later load hang. The cap is on the
 * total dimensions, not on a single request, because repeated inserts would
 * otherwise bypass a per-request limit.
 */
export const MAX_ROW_COUNT = 10000;
export const MAX_COL_COUNT = 256;

