edits.newText:
  const updated = getWorksheetRow(db, ws.id);
  if (!updated) throw notFound('Worksheet not found');
  const workbook = getWorkbookSnapshot(db, ws.workbook_id);
  if (!workbook) throw notFound('Workbook not found');
  return workbook;
}

/**
 * First unused `<prefix>N` name in positive-integer order, derived from the
 * existing names (no persisted counter). Used for `SheetN`; exported with a
 * configurable prefix so the pivot `PivotN` derivation can reuse it.
 *
 * @param {Db} db
 * @param {string} workbookId
 * @param {string} [prefix]
 * @returns {string}
 */
export function deriveWorksheetName(db, workbookId, prefix = 'Sheet') {
  const names = new Set(
    /** @type {{ name: string }[]} */ (
      db.prepare('SELECT name FROM worksheets WHERE workbook_id = ?').all(workbookId)
    ).map((row) => row.name),
  );
  let n = 1;
  while (names.has(`${prefix}${n}`)) n += 1;
  return `${prefix}${n}`;
}

/**
 * Add a blank worksheet and make it active (REQ-2-1-1). The optional `name`
 * goes through the same trim/non-empty/unique checks as the rename endpoint;
 * without it the first unused `SheetN` is derived. The new worksheet never
 * inherits filters, validation or pivots and selects A1.
 *
 * @param {Db} db
 * @param {string} workbookId
 * @param {unknown} rawName
 * @returns {WorkbookSnapshot}
 */
export function createWorksheet(db, workbookId, rawName) {
  const wb = getWorkbookRow(db, workbookId);
  if (!wb) throw notFound('Workbook not found');
  const id = newId('ws');
  const at = nowIso();
  db.transaction(() => {
    let name;
    if (rawName === undefined || rawName === null) {
      name = deriveWorksheetName(db, workbookId);
    } else {
      if (typeof rawName !== 'string') throw invalidBody('Worksheet name must be a string');
      name = rawName.trim();
      if (!name) throw validationError('Worksheet name cannot be empty');
      assertWorksheetNameAvailable(db, workbookId, null, name);
    }
    const maxPosition = /** @type {{ p: number }} */ (
      db
        .prepare('SELECT COALESCE(MAX(position), -1) AS p FROM worksheets WHERE workbook_id = ?')
        .get(workbookId)
    ).p;
    db.prepare('UPDATE worksheets SET last_active = 0 WHERE workbook_id = ?').run(workbookId);
    db.prepare(
      `INSERT INTO worksheets (id, workbook_id, name, position, row_count, col_count, last_active, last_selection)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
    ).run(
      id,
      workbookId,
      name,
      maxPosition + 1,
      DEFAULT_ROW_COUNT,
      DEFAULT_COL_COUNT,
      1,
      JSON.stringify(DEFAULT_SELECTION),
    );
    touchWorkbook(db, workbookId, at);
  })();
  const snapshot = getWorkbookSnapshot(db, workbookId);
  if (!snapshot) throw notFound('Workbook not found');
  return snapshot;
}

/**
 * Delete a worksheet and activate an adjacent one (REQ-2-1-4).
 *
 * Both `pivots` foreign keys cascade, so a pivot whose source is the target
 * would be silently deleted before any check could run: the dependency check
 * therefore happens first (Issue #4 comment #35 D-B1). Deleting a pivot *result*
 * worksheet still cascades the pivot row, which is exactly the required
 * "source is no longer constrained by that pivot".
 *
 * @param {Db} db
 * @param {WorksheetRow} ws
 * @returns {WorkbookSnapshot}
 */
export function deleteWorksheet(db, ws) {
  const workbookId = ws.workbook_id;
  const at = nowIso();
  db.transaction(() => {
    const siblings = /** @type {{ id: string }[]} */ (
      db
        .prepare('SELECT id FROM worksheets WHERE workbook_id = ? ORDER BY position, rowid')
        .all(workbookId)
    );
    if (siblings.length <= 1) {
      throw new ApiError(
        409,
        'VALIDATION_ERROR',
        'A workbook must contain at least one worksheet',
      );
    }
    const dependency = db
      .prepare('SELECT id FROM pivots WHERE source_worksheet_id = ? LIMIT 1')
      .get(ws.id);
    if (dependency) {
      throw new ApiError(
        409,
        'VALIDATION_ERROR',
        'Please delete or rebuild dependent pivot tables first',
      );
    }
    const index = siblings.findIndex((sibling) => sibling.id === ws.id);
    const wasActive = ws.last_active === 1;
    db.prepare('DELETE FROM worksheets WHERE id = ?').run(ws.id);
    if (wasActive) {
      const neighbor = siblings[index + 1] ?? siblings[index - 1];
      db.prepare('UPDATE worksheets SET last_active = 0 WHERE workbook_id = ?').run(workbookId);
      db.prepare('UPDATE worksheets SET last_active = 1 WHERE id = ?').run(neighbor.id);
    }
    touchWorkbook(db, workbookId, at);
  })();
  const snapshot = getWorkbookSnapshot(db, workbookId);
  if (!snapshot) throw notFound('Workbook not found');
  return snapshot;
}

/**
 * Move every stored cell on one axis by `delta`, in place, without colliding
 * with the `(worksheet_id, row, col)` primary key. A plain `SET row = row + 1`
 * fails with `UNIQUE constraint failed` because SQLite updates row by row and
 * each new value can still be occupied (verified on better-sqlite3 12.6.2).
 *
 * @param {Db} db
 * @param {string} worksheetId
 * @param {'row' | 'column'} axis
 * @param {string} where e.g. `row >= ?`; placeholders follow.
 * @param {number[]} params
 * @param {number} delta
 * @returns {void}
 */
function shiftCells(db, worksheetId, axis, where, params, delta) {
  const column = axis === 'row' ? 'row' : 'col';
  db.prepare(
    `UPDATE cells SET ${column} = ${column} + ? WHERE worksheet_id = ? AND ${where}`,
  ).run(SHIFT_OFFSET, worksheetId, ...params);
  db.prepare(
    `UPDATE cells SET ${column} = ${column} - ? + ? WHERE worksheet_id = ? AND ${column} >= ?`,
  ).run(SHIFT_OFFSET, delta, worksheetId, SHIFT_OFFSET + (params[0] ?? 0));
}

/**
 * Shift validation rules, filters and pivot source ranges in the same
 * transaction as the cell movement (Issue #4 comment #35 D-B3). Ranges that
 * collapse on deletion are removed; pivot ranges that moved are marked stale
 * so the retained result is recomputed only on "Refresh pivot table".
 *
 * @param {Db} db
 * @param {string} worksheetId
 * @param {'row' | 'column'} axis
 * @param {{ kind: 'insert', at: number, count: number } | { kind: 'delete', at: number }} op
 * @returns {void}
 */
function shiftStoredRanges(db, worksheetId, axis, op) {
  /**
   * @param {string} range
   * @returns {{ range: string | null, changed: boolean }}
   */
  const shift = (range) =>
    op.kind === 'insert'
      ? shiftRangeOnInsert(range, axis, op.at, op.count)
      : shiftRangeOnDelete(range, axis, op.at);

  for (const table of ['validation_rules', 'filters']) {
    const rows = /** @type {{ id: string, range: string }[]} */ (
      db.prepare(`SELECT id, range FROM ${table} WHERE worksheet_id = ?`).all(worksheetId)
    );
    for (const row of rows) {
      const result = shift(row.range);
      if (result.range === null) {
        db.prepare(`DELETE FROM ${table} WHERE id = ?`).run(row.id);
      } else if (result.changed) {
        db.prepare(`UPDATE ${table} SET range = ? WHERE id = ?`).run(result.range, row.id);
      }
    }
  }

  const pivots = /** @type {{ id: string, source_range: string }[]} */ (
    db
      .prepare('SELECT id, source_range FROM pivots WHERE source_worksheet_id = ?')
      .all(worksheetId)
  );
  for (const pivot of pivots) {
    const result = shift(pivot.source_range);
    if (result.range === null) {
      // A source range with no rows/columns left cannot be refreshed; keeping
      // the pivot would leave a range the structure can never render.
      db.prepare('DELETE FROM pivots WHERE id = ?').run(pivot.id);
    } else if (result.changed) {
      db.prepare('UPDATE pivots SET source_range = ?, stale = 1 WHERE id = ?').run(
        result.range,
        pivot.id,
      );
    }
  }
}

/**
 * Move the persisted `last_selection` rectangle with the same coordinate
 * mapping used for cells (Issue #4 comment #35 D-B2). An insertion that splits
 * the rectangle expands it; a deletion that empties it resets to A1.
 *
 * @param {Db} db
 * @param {WorksheetRow} ws
 * @param {'row' | 'column'} axis
 * @param {{ kind: 'insert', at: number, count: number } | { kind: 'delete', at: number }} op
 * @returns {void}
 */
function shiftSelection(db, ws, axis, op) {
  const selection = parseJson(ws.last_selection, /** @type {SelectionRect | null} */ (null));
  if (!selection || typeof selection !== 'object') return;
  const insert = (/** @type {number} */ c) =>
    c >= op.at ? c + (op.kind === 'insert' ? op.count : 0) : c;
  // `top` clamps at 0 so a deletion at index 0 keeps the rectangle anchored;
  // `bottom` may drop to -1, which is how an emptied rectangle is detected.
  const top = (/** @type {number} */ c) =>
    op.kind === 'insert' ? insert(c) : c < op.at ? c : Math.max(0, c - 1);
  const bottom = (/** @type {number} */ c) =>
    op.kind === 'insert' ? insert(c) : c < op.at ? c : c - 1;
  const rowAxis = axis === 'row';
  /** @type {SelectionRect} */
  const next = rowAxis
    ? {
        ...selection,
        r1: top(selection.r1),
        r2: bottom(selection.r2),
        anchor: { ...selection.anchor, row: top(selection.anchor.row) },
      }
    : {
        ...selection,
        c1: top(selection.c1),
        c2: bottom(selection.c2),
        anchor: { ...selection.anchor, col: top(selection.anchor.col) },
      };
  const emptied = next.r1 > next.r2 || next.c1 > next.c2;
  db.prepare('UPDATE worksheets SET last_selection = ? WHERE id = ?').run(
    JSON.stringify(emptied ? DEFAULT_SELECTION : next),
    ws.id,
  );
}

/**
 * Structural insert on one axis (contract endpoint 8 / REQ-2-2-1/2).
 *
 * @param {Db} db
 * @param {WorksheetRow} ws
 * @param {'row' | 'column'} axis
