edits.newText:
  // Selection persistence (contract §2.9): the last confirmed rectangle.
  router.put('/workbooks/:id/worksheets/:wid/selection', (req, res) => {
    const ws = requireWorksheet(db, req.params.id, req.params.wid);
    const selection = parseSelection(req.body);
    assertSelectionInBounds(selection, ws.row_count, ws.col_count);
    setSelection(db, ws, selection);
    res.json({ ok: true, selection });
  });

  // Worksheet rename / activation. Answers with the full workbook snapshot
  // (contract endpoint 7; Issue #4 comment #35 D-B1).
  router.patch('/workbooks/:id/worksheets/:wid', (req, res) => {
    const ws = requireWorksheet(db, req.params.id, req.params.wid);
    const body = asObject(req.body ?? {});
    res.json(patchWorksheet(db, ws, { name: body.name, isActive: body.isActive }));
  });

  // 7. Add a worksheet (REQ-2-1-1) / delete one (REQ-2-1-4).
  router.post('/workbooks/:id/worksheets', (req, res) => {
    const body = asObject(req.body ?? {});
    res.status(201).json(createWorksheet(db, req.params.id, body.name));
  });

  router.delete('/workbooks/:id/worksheets/:wid', (req, res) => {
    const ws = requireWorksheet(db, req.params.id, req.params.wid);
    res.json(deleteWorksheet(db, ws));
  });

  // 8. Row/column structure (REQ-2-2-1 / REQ-2-2-2).
  router.post('/workbooks/:id/worksheets/:wid/rows', (req, res) => {
    const ws = requireWorksheet(db, req.params.id, req.params.wid);
    res.json(insertStructure(db, ws, 'row', parseInsertRequest(req.body, 'row')));
  });

  router.delete('/workbooks/:id/worksheets/:wid/rows/:index', (req, res) => {
    const ws = requireWorksheet(db, req.params.id, req.params.wid);
    res.json(deleteStructure(db, ws, 'row', parseIndexParam(req.params.index)));
  });

  router.post('/workbooks/:id/worksheets/:wid/cols', (req, res) => {
    const ws = requireWorksheet(db, req.params.id, req.params.wid);
    res.json(insertStructure(db, ws, 'column', parseInsertRequest(req.body, 'column')));
  });

  router.delete('/workbooks/:id/worksheets/:wid/cols/:index', (req, res) => {
    const ws = requireWorksheet(db, req.params.id, req.params.wid);
    res.json(deleteStructure(db, ws, 'column', parseIndexParam(req.params.index)));
  });

  return router;
}

