arguments.content:
/**
 * Sub-issue B acceptance tests (Issue #4 REQ-2-1-* / REQ-2-2-*): worksheet
 * lifecycle, row/column structure endpoints, the shared A1 range mapping and
 * the selection rules decided in Issue #4 comment #35 (D-B1…D-B3).
 */
import { describe, expect, it } from 'vitest';
import request from 'supertest';
import { openDatabase } from './db.js';
import { SEED_SHEET1_ID, SEED_SHEET2_ID, SEED_WORKBOOK_ID, seedDatabase } from './seed.js';
import { createApp } from './app.js';
import { deriveWorksheetName, MAX_COL_COUNT, MAX_ROW_COUNT } from './store.js';
import { formatA1Range, parseA1Range, shiftRangeOnDelete, shiftRangeOnInsert } from './ranges.js';

function freshDb() {
  const db = openDatabase(':memory:');
  seedDatabase(db);
  return db;
}

/** @param {import('./db.js').Db} db */
function appFor(db) {
  return createApp(db, { frontendDist: null });
}

/**
 * @param {import('supertest').SuperTest<import('supertest').Test>} app
 * @param {string} [worksheetId]
 */
function snapshot(app, worksheetId = SEED_SHEET1_ID) {
  return request(app)
    .get(`/api/workbooks/${SEED_WORKBOOK_ID}`)
    .then((res) => ({
      workbook: res.body,
      sheet: res.body.worksheets.find(
        (/** @type {{ id: string }} */ w) => w.id === worksheetId,
      ),
    }));
}

/** @param {import('./db.js').Db} db */
function sheetCells(db, worksheetId) {
  return /** @type {{ row: number, col: number, raw: string }[]} */ (
    db
      .prepare('SELECT row, col, raw FROM cells WHERE worksheet_id = ? ORDER BY row, col')
      .all(worksheetId)
  );
}

/**
 * @param {import('./db.js').Db} db
 * @param {string} worksheetId
 * @param {{ row: number, col: number, raw: string }[]} cells
 */
function setCells(db, worksheetId, cells) {
  db.prepare('DELETE FROM cells WHERE worksheet_id = ?').run(worksheetId);
  const insert = db.prepare('INSERT INTO cells (worksheet_id, row, col, raw) VALUES (?, ?, ?, ?)');
  for (const cell of cells) insert.run(worksheetId, cell.row, cell.col, cell.raw);
}

describe('ranges: A1 parsing and structural mapping', () => {
  it('round-trips single cells and rectangles', () => {
    expect(parseA1Range('B2')).toEqual({ r1: 1, c1: 1, r2: 1, c2: 1 });
    expect(parseA1Range('B2:D10')).toEqual({ r1: 1, c1: 1, r2: 9, c2: 3 });
    expect(parseA1Range('$B$2:$D$10')).toEqual({ r1: 1, c1: 1, r2: 9, c2: 3 });
    expect(formatA1Range({ r1: 1, c1: 1, r2: 1, c2: 1 })).toBe('B2');
    expect(formatA1Range({ r1: 1, c1: 1, r2: 9, c2: 3 })).toBe('B2:D10');
    expect(parseA1Range('not a range')).toBeNull();
  });

  it('shifts, expands and leaves ranges alone on insertion', () => {
    expect(shiftRangeOnInsert('B2:B10', 'row', 1, 1)).toEqual({ range: 'B3:B11', changed: true });
    expect(shiftRangeOnInsert('B2:B10', 'row', 5, 2)).toEqual({ range: 'B2:B12', changed: true });
    expect(shiftRangeOnInsert('B2:B10', 'row', 20, 1)).toEqual({ range: 'B2:B10', changed: false });
    expect(shiftRangeOnInsert('A1:XFD10000', 'column', 0, 1).range).toBe('B1:XFE10000');
  });

  it('shrinks intersecting ranges with r2 -= 1 and removes collapsed ones', () => {
    // The counterexample recorded in D-B3: deleting row 2 from A2:A5 must keep
    // the shifted data (old rows 3-5) inside the rule, i.e. A2:A4, not A3:A5.
    expect(shiftRangeOnDelete('B2:B5', 'row', 1)).toEqual({ range: 'B2:B4', changed: true });
    expect(shiftRangeOnDelete('B2:B10', 'row', 0)).toEqual({ range: 'B1:B9', changed: true });
    expect(shiftRangeOnDelete('B2:B10', 'row', 20)).toEqual({ range: 'B2:B10', changed: false });
    expect(shiftRangeOnDelete('B2:B2', 'row', 1)).toEqual({ range: null, changed: true });
    expect(shiftRangeOnDelete('B2:D4', 'column', 1)).toEqual({ range: 'B2:C4', changed: true });
  });
});

describe('worksheet name derivation', () => {
  it('returns the first unused SheetN in positive-integer order', () => {
    const db = freshDb();
    expect(deriveWorksheetName(db, SEED_WORKBOOK_ID)).toBe('Sheet3');
    db.prepare(
      `INSERT INTO worksheets (id, workbook_id, name, position, row_count, col_count, last_active, last_selection)
       VALUES ('ws-extra', ?, 'Sheet4', 9, 6, 26, 0, NULL)`,
    ).run(SEED_WORKBOOK_ID);
    expect(deriveWorksheetName(db, SEED_WORKBOOK_ID)).toBe('Sheet3');
    db.prepare(
      `INSERT INTO worksheets (id, workbook_id, name, position, row_count, col_count, last_active, last_selection)
       VALUES ('ws-extra3', ?, 'Sheet3', 10, 6, 26, 0, NULL)`,
    ).run(SEED_WORKBOOK_ID);
    expect(deriveWorksheetName(db, SEED_WORKBOOK_ID)).toBe('Sheet5');
  });

  it('supports the PivotN prefix used by the pivot sub-issue', () => {
    const db = freshDb();
    db.prepare(
      `INSERT INTO worksheets (id, workbook_id, name, position, row_count, col_count, last_active, last_selection)
       VALUES ('ws-pivot1', ?, 'Pivot1', 9, 6, 26, 0, NULL)`,
    ).run(SEED_WORKBOOK_ID);
    expect(deriveWorksheetName(db, SEED_WORKBOOK_ID, 'Pivot')).toBe('Pivot2');
    // The Sheet prefix is unaffected by pivot result sheets.
    expect(deriveWorksheetName(db, SEED_WORKBOOK_ID)).toBe('Sheet3');
  });
});

describe('POST /api/workbooks/:id/worksheets', () => {
  it('adds a blank active SheetN that does not inherit anything (REQ-2-1-1)', async () => {
    const db = freshDb();
    const app = appFor(db);
    // Give Sheet1 filter/validation/pivot state that must not be inherited.
    db.prepare(
      `INSERT INTO validation_rules (id, worksheet_id, kind, range, params)
       VALUES ('vr-1', ?, 'number', 'B2:B5', '{}')`,
    ).run(SEED_SHEET1_ID);
    db.prepare(
      `INSERT INTO filters (id, worksheet_id, range, column_specs)
       VALUES ('flt-1', ?, 'A1:C6', '[]')`,
    ).run(SEED_SHEET1_ID);

    const res = await request(app).post(`/api/workbooks/${SEED_WORKBOOK_ID}/worksheets`).send({});
    expect(res.status).toBe(201);
    expect(res.body.worksheets).toHaveLength(3);
    const created = res.body.worksheets[2];
    expect(created).toMatchObject({
      name: 'Sheet3',
      position: 2,
      isActive: true,
      rowCount: 6,
      colCount: 26,
      cells: [],
      validations: [],
      filters: [],
      pivots: [],
    });
    expect(created.lastSelection).toMatchObject({ r1: 0, c1: 0, r2: 0, c2: 0 });
    expect(res.body.worksheets[0].isActive).toBe(false);

    // Full snapshot shape (D-B1) and refresh persistence.
    const after = await snapshot(app);
    expect(after.workbook.worksheets).toHaveLength(3);
    expect(after.workbook.worksheets[2].name).toBe('Sheet3');
  });

  it('accepts an explicit name with the same rules as rename', async () => {
    const app = appFor(freshDb());
    const ok = await request(app)
      .post(`/api/workbooks/${SEED_WORKBOOK_ID}/worksheets`)
      .send({ name: '  Data  ' });
    expect(ok.status).toBe(201);
    expect(ok.body.worksheets[2].name).toBe('Data');

    const duplicate = await request(app)
      .post(`/api/workbooks/${SEED_WORKBOOK_ID}/worksheets`)
      .send({ name: 'Sheet1' });
    expect(duplicate.status).toBe(409);
    expect(duplicate.body).toEqual({
      error: { code: 'VALIDATION_ERROR', message: 'Worksheet name already exists' },
    });

    const empty = await request(app)
      .post(`/api/workbooks/${SEED_WORKBOOK_ID}/worksheets`)
      .send({ name: '   ' });
    expect(empty.status).toBe(400);
    expect(empty.body.error.message).toBe('Worksheet name cannot be empty');

    // A failed addition leaves no extra worksheet behind.
    const after = await snapshot(app);
    expect(after.workbook.worksheets).toHaveLength(3);
  });

  it('rejects an unknown workbook', async () => {
    const res = await request(appFor(freshDb())).post('/api/workbooks/nope/worksheets').send({});
    expect(res.status).toBe(404);
  });
});

describe('DELETE /api/workbooks/:id/worksheets/:wid', () => {
  it('deletes the active worksheet and activates the right neighbour (REQ-2-1-4)', async () => {
    const app = appFor(freshDb());
    const res = await request(app).delete(
      `/api/workbooks/${SEED_WORKBOOK_ID}/worksheets/${SEED_SHEET1_ID}`,
    );
    expect(res.status).toBe(200);
    expect(res.body.worksheets).toHaveLength(1);
    expect(res.body.worksheets[0]).toMatchObject({ id: SEED_SHEET2_ID, isActive: true });

    const after = await snapshot(app, SEED_SHEET2_ID);
    expect(after.workbook.worksheets).toHaveLength(1);
  });

  it('activates the left neighbour when the deleted tab is last', async () => {
    const app = appFor(freshDb());
    // Make Sheet2 active, then delete it.
    await request(app)
      .patch(`/api/workbooks/${SEED_WORKBOOK_ID}/worksheets/${SEED_SHEET2_ID}`)
      .send({ isActive: true });
    const res = await request(app).delete(
      `/api/workbooks/${SEED_WORKBOOK_ID}/worksheets/${SEED_SHEET2_ID}`,
    );
    expect(res.body.worksheets).toHaveLength(1);
    expect(res.body.worksheets[0]).toMatchObject({ id: SEED_SHEET1_ID, isActive: true });
  });

  it('keeps the active worksheet when an inactive one is deleted', async () => {
    const app = appFor(freshDb());
    const res = await request(app).delete(
      `/api/workbooks/${SEED_WORKBOOK_ID}/worksheets/${SEED_SHEET2_ID}`,
    );
    expect(res.body.worksheets).toHaveLength(1);
    expect(res.body.worksheets[0]).toMatchObject({ id: SEED_SHEET1_ID, isActive: true });
  });

  it('refuses to delete the last worksheet', async () => {
    const app = appFor(freshDb());
    await request(app).delete(`/api/workbooks/${SEED_WORKBOOK_ID}/worksheets/${SEED_SHEET1_ID}`);
    const res = await request(app).delete(
      `/api/workbooks/${SEED_WORKBOOK_ID}/worksheets/${SEED_SHEET2_ID}`,
    );
    expect(res.status).toBe(409);
    expect(res.body).toEqual({
      error: {
        code: 'VALIDATION_ERROR',
        message: 'A workbook must contain at least one worksheet',
      },
    });
    const after = await snapshot(app, SEED_SHEET2_ID);
    expect(after.workbook.worksheets).toHaveLength(1);
  });

  it('rejects deleting a pivot source before the cascade can hide it', async () => {
    const db = freshDb();
    const app = appFor(db);
    db.prepare(
      `INSERT INTO pivots (id, source_worksheet_id, source_range, config, result_worksheet_id, last_result, stale)
       VALUES ('pvt-1', ?, 'A1:B4', '{}', ?, NULL, 0)`,
    ).run(SEED_SHEET1_ID, SEED_SHEET2_ID);

    const res = await request(app).delete(
      `/api/workbooks/${SEED_WORKBOOK_ID}/worksheets/${SEED_SHEET1_ID}`,
    );
    expect(res.status).toBe(409);
    expect(res.body).toEqual({
      error: {
        code: 'VALIDATION_ERROR',
        message: 'Please delete or rebuild dependent pivot tables first',
      },
    });
    // Neither the worksheet nor the pivot changed.
    const after = await snapshot(app, SEED_SHEET1_ID);
    expect(after.workbook.worksheets).toHaveLength(2);
    expect(db.prepare('SELECT COUNT(*) AS n FROM pivots').get()).toEqual({ n: 1 });
  });

  it('releases the source constraint when the pivot result worksheet is deleted', async () => {
    const db = freshDb();
    const app = appFor(db);
    db.prepare(
      `INSERT INTO pivots (id, source_worksheet_id, source_range, config, result_worksheet_id, last_result, stale)
       VALUES ('pvt-1', ?, 'A1:B4', '{}', ?, NULL, 0)`,
    ).run(SEED_SHEET1_ID, SEED_SHEET2_ID);

    const deleted = await request(app).delete(
      `/api/workbooks/${SEED_WORKBOOK_ID}/worksheets/${SEED_SHEET2_ID}`,
    );
    expect(deleted.status).toBe(200);
    expect(db.prepare('SELECT COUNT(*) AS n FROM pivots').get()).toEqual({ n: 0 });
    // Sheet1 is no longer a pivot source, so it can be deleted (but it is the
    // last one now; add a replacement to prove the constraint is gone).
    const added = await request(app)
      .post(`/api/workbooks/${SEED_WORKBOOK_ID}/worksheets`)
      .send({ name: 'Extra' });
    expect(added.status).toBe(201);
    const again = await request(app).delete(
      `/api/workbooks/${SEED_WORKBOOK_ID}/worksheets/${SEED_SHEET1_ID}`,
    );
    expect(again.status).toBe(200);
  });

  it('removes the target worksheet data with it', async () => {
    const db = freshDb();
    const app = appFor(db);
    await request(app).delete(`/api/workbooks/${SEED_WORKBOOK_ID}/worksheets/${SEED_SHEET1_ID}`);
    expect(sheetCells(db, SEED_SHEET1_ID)).toHaveLength(0);
  });
});

describe('POST/DELETE rows and columns', () => {
  it('inserts one row above and shifts cells, counts and structure', async () => {
    const db = freshDb();
    const app = appFor(db);
    const res = await request(app)
      .post(`/api/workbooks/${SEED_WORKBOOK_ID}/worksheets/${SEED_SHEET1_ID}/rows`)
      .send({ index: 1, count: 1, side: 'above' });
    expect(res.status).toBe(200);
    expect(res.body.id).toBe(SEED_WORKBOOK_ID);
    const sheet = res.body.worksheets.find(
      (/** @type {{ id: string }} */ w) => w.id === SEED_SHEET1_ID,
    );
    expect(sheet.rowCount).toBe(7);
    expect(sheet.colCount).toBe(26);
    // Row 1 is blank; every original row >= 1 moved down one.
    expect(sheet.cells).toContainEqual([0, 0, 'Region']);
    expect(sheet.cells).toContainEqual([2, 0, 'East']);
    expect(sheet.cells).toContainEqual([3, 0, 'North']);
    expect(sheet.cells).toContainEqual([4, 0, 'South']);
    const refreshed = await snapshot(app);
    expect(refreshed.sheet.rowCount).toBe(7);
    expect(refreshed.sheet.cells).toContainEqual([2, 0, 'East']);
  });

  it('inserts one row below the last row without a special-case bound', async () => {
    const db = freshDb();
    const app = appFor(db);
    const before = await snapshot(app);
    const res = await request(app)
      .post(`/api/workbooks/${SEED_WORKBOOK_ID}/worksheets/${SEED_SHEET1_ID}/rows`)
      .send({ index: 5, count: 1, side: 'below' });
    expect(res.status).toBe(200);
    const sheet = res.body.worksheets[0];
    expect(sheet.rowCount).toBe(7);
    expect(sheet.cells).toEqual(before.sheet.cells);
  });

  it('deletes a row and shifts subsequent cells up', async () => {
    const db = freshDb();
    const app = appFor(db);
    const res = await request(app).delete(
      `/api/workbooks/${SEED_WORKBOOK_ID}/worksheets/${SEED_SHEET1_ID}/rows/1`,
    );
    expect(res.status).toBe(200);
    const sheet = res.body.worksheets[0];
    expect(sheet.rowCount).toBe(5);
    expect(sheet.cells).toContainEqual([1, 0, 'North']);
    expect(sheet.cells).toContainEqual([2, 0, 'South']);
    expect(sheet.cells.some((/** @type {unknown[]} */ c) => c[2] === 'East')).toBe(false);
  });

  it('inserts and deletes columns symmetrically', async () => {
    const db = freshDb();
    const app = appFor(db);
    const inserted = await request(app)
      .post(`/api/workbooks/${SEED_WORKBOOK_ID}/worksheets/${SEED_SHEET1_ID}/cols`)
      .send({ index: 1, count: 1, side: 'left' });
    expect(inserted.status).toBe(200);
    let sheet = inserted.body.worksheets[0];
    expect(sheet.colCount).toBe(27);
    expect(sheet.cells).toContainEqual([0, 0, 'Region']);
    expect(sheet.cells).toContainEqual([0, 2, 'Sales']);

    const deleted = await request(app).delete(
      `/api/workbooks/${SEED_WORKBOOK_ID}/worksheets/${SEED_SHEET1_ID}/cols/1`,
    );
    expect(deleted.status).toBe(200);
    sheet = deleted.body.worksheets[0];
    expect(sheet.colCount).toBe(26);
    expect(sheet.cells).toContainEqual([0, 1, 'Sales']);
  });

  it('never touches other worksheets', async () => {
    const app = appFor(freshDb());
    await request(app)
      .post(`/api/workbooks/${SEED_WORKBOOK_ID}/worksheets/${SEED_SHEET1_ID}/rows`)
      .send({ index: 0, count: 3, side: 'above' });
    const after = await snapshot(app, SEED_SHEET2_ID);
    expect(after.sheet).toMatchObject({ rowCount: 6, colCount: 26, cells: [] });
  });
});

describe('structure-driven range migration (D-B3)', () => {
  /** @param {import('./db.js').Db} db */
  function withRule(db, range) {
    db.prepare(
      `INSERT INTO validation_rules (id, worksheet_id, kind, range, params)
       VALUES ('vr-1', ?, 'number', ?, '{"min":0,"max":100}')`,
    ).run(SEED_SHEET1_ID, range);
  }

  it('expands a rule whose body receives the inserted row, leaves outside rules alone', async () => {
    const db = freshDb();
    const app = appFor(db);
    withRule(db, 'B2:B5');
    await request(app)
      .post(`/api/workbooks/${SEED_WORKBOOK_ID}/worksheets/${SEED_SHEET1_ID}/rows`)
      .send({ index: 2, count: 1, side: 'above' });
    const rule = db.prepare('SELECT range FROM validation_rules WHERE id = ?').get('vr-1');
    expect(rule).toEqual({ range: 'B2:B6' });
  });

  it('shrinks an intersecting rule with r2 -= 1 on deletion', async () => {
    const db = freshDb();
    const app = appFor(db);
    withRule(db, 'B2:B5');
    await request(app).delete(
      `/api/workbooks/${SEED_WORKBOOK_ID}/worksheets/${SEED_SHEET1_ID}/rows/1`,
    );
    const rule = db.prepare('SELECT range FROM validation_rules WHERE id = ?').get('vr-1');
    expect(rule).toEqual({ range: 'B2:B4' });
  });

  it('removes a single-cell rule that lands exactly on the deleted row', async () => {
    const db = freshDb();
    const app = appFor(db);
    withRule(db, 'A3:A3');
    await request(app).delete(
      `/api/workbooks/${SEED_WORKBOOK_ID}/worksheets/${SEED_SHEET1_ID}/rows/2`,
    );
    expect(db.prepare('SELECT COUNT(*) AS n FROM validation_rules').get()).toEqual({ n: 0 });
  });

  it('migrates filter ranges with the same helper', async () => {
    const db = freshDb();
    const app = appFor(db);
    db.prepare(
      `INSERT INTO filters (id, worksheet_id, range, column_specs)
       VALUES ('flt-1', ?, 'A1:C6', '[]')`,
    ).run(SEED_SHEET1_ID);
    await request(app)
      .post(`/api/workbooks/${SEED_WORKBOOK_ID}/worksheets/${SEED_SHEET1_ID}/cols`)
      .send({ index: 1, count: 2, side: 'right' });
    expect(db.prepare('SELECT range FROM filters WHERE id = ?').get('flt-1')).toEqual({
      range: 'A1:E6',
    });
    await request(app).delete(
      `/api/workbooks/${SEED_WORKBOOK_ID}/worksheets/${SEED_SHEET1_ID}/cols/0`,
    );
    expect(db.prepare('SELECT range FROM filters WHERE id = ?').get('flt-1')).toEqual({
      range: 'A1:D6',
    });
  });

  it('shifts the pivot source range and marks it stale', async () => {
    const db = freshDb();
    const app = appFor(db);
    db.prepare(
      `INSERT INTO pivots (id, source_worksheet_id, source_range, config, result_worksheet_id, last_result, stale)
       VALUES ('pvt-1', ?, 'B2:C5', '{}', ?, NULL, 0)`,
    ).run(SEED_SHEET1_ID, SEED_SHEET2_ID);
    await request(app)
      .post(`/api/workbooks/${SEED_WORKBOOK_ID}/worksheets/${SEED_SHEET1_ID}/rows`)
      .send({ index: 2, count: 1, side: 'above' });
    expect(db.prepare('SELECT source_range, stale FROM pivots WHERE id = ?').get('pvt-1')).toEqual({
      source_range: 'B2:C6',
      stale: 1,
    });
  });
});

describe('structure-driven selection migration (D-B2)', () => {
