      .post(`/api/workbooks/${SEED_WORKBOOK_ID}/worksheets/${SEED_SHEET1_ID}/rows`)
      .send({ index: 0, count: 1, side: 'above' });
    expect(res.body.worksheets[0].lastSelection).toEqual({
      r1: 2,
      c1: 0,
      r2: 4,
      c2: 2,
      anchor: { row: 2, col: 0 },
    });
  });

  it('expands a selection that the insertion splits', async () => {
    const app = appFor(freshDb());
    await request(app)
      .put(`/api/workbooks/${SEED_WORKBOOK_ID}/worksheets/${SEED_SHEET1_ID}/selection`)
      .send({ r1: 0, c1: 0, r2: 3, c2: 2, anchor: { row: 0, col: 0 } });
