describe('structure failure atomicity and guards', () => {
  it('rejects an out-of-range index without moving anything', async () => {
    const app = appFor(freshDb());
    const before = await snapshot(app);
    const res = await request(app)
      .post(`/api/workbooks/${SEED_WORKBOOK_ID}/worksheets/${SEED_SHEET1_ID}/rows`)
      .send({ index: 6, count: 1, side: 'above' });
    expect(res.status).toBe(400);
    const after = await snapshot(app);
    expect(after.sheet).toEqual(before.sheet);
  });

  it('rejects an unknown side and a non-positive count', async () => {
    const app = appFor(freshDb());
    const before = await snapshot(app);
    for (const body of [
      { index: 0, count: 1, side: 'middle' },
      { index: 0, count: 0, side: 'above' },
      { index: -1, count: 1, side: 'above' },
    ]) {
      const res = await request(app)
        .post(`/api/workbooks/${SEED_WORKBOOK_ID}/worksheets/${SEED_SHEET1_ID}/rows`)
        .send(body);
      expect(res.status).toBe(400);
    }
    const after = await snapshot(app);
    expect(after.sheet).toEqual(before.sheet);
  });

  it('refuses to delete the last row or column of a worksheet', async () => {
    const app = appFor(freshDb());
    await request(app)
      .put(`/api/workbooks/${SEED_WORKBOOK_ID}/worksheets/${SEED_SHEET1_ID}/state`)
      .send({ rowCount: 1, colCount: 1, cells: [] });
    const rowRes = await request(app).delete(
      `/api/workbooks/${SEED_WORKBOOK_ID}/worksheets/${SEED_SHEET1_ID}/rows/0`,
    );
    expect(rowRes.status).toBe(400);
    expect(rowRes.body.error.code).toBe('INVALID_BODY');
    const colRes = await request(app).delete(
      `/api/workbooks/${SEED_WORKBOOK_ID}/worksheets/${SEED_SHEET1_ID}/cols/0`,
    );
    expect(colRes.status).toBe(400);
    const after = await snapshot(app);
    expect(after.sheet).toMatchObject({ rowCount: 1, colCount: 1 });
  });

  it('enforces the defensive total-dimension caps', async () => {
    const db = freshDb();
    const app = appFor(db);
    await request(app)
      .put(`/api/workbooks/${SEED_WORKBOOK_ID}/worksheets/${SEED_SHEET1_ID}/state`)
      .send({ rowCount: MAX_ROW_COUNT - 1, colCount: 26, cells: [] });
    const tooManyRows = await request(app)
      .post(`/api/workbooks/${SEED_WORKBOOK_ID}/worksheets/${SEED_SHEET1_ID}/rows`)
      .send({ index: 0, count: 10, side: 'above' });
    expect(tooManyRows.status).toBe(400);
    expect(tooManyRows.body.error.code).toBe('INVALID_BODY');

    await request(app)
      .put(`/api/workbooks/${SEED_WORKBOOK_ID}/worksheets/${SEED_SHEET1_ID}/state`)
      .send({ rowCount: 6, colCount: MAX_COL_COUNT, cells: [] });
    const tooManyCols = await request(app)
      .post(`/api/workbooks/${SEED_WORKBOOK_ID}/worksheets/${SEED_SHEET1_ID}/cols`)
      .send({ index: 0, count: 1, side: 'left' });
    expect(tooManyCols.status).toBe(400);
  });

  it('works on non-default imported dimensions', async () => {
    const db = freshDb();
    const app = appFor(db);
    await request(app)
      .put(`/api/workbooks/${SEED_WORKBOOK_ID}/worksheets/${SEED_SHEET1_ID}/state`)
      .send({ rowCount: 42, colCount: 7, cells: [[41, 6, 'corner']] });
    const res = await request(app)
      .post(`/api/workbooks/${SEED_WORKBOOK_ID}/worksheets/${SEED_SHEET1_ID}/rows`)
      .send({ index: 41, count: 1, side: 'below' });
    expect(res.status).toBe(200);
    const sheet = res.body.worksheets[0];
    expect(sheet).toMatchObject({ rowCount: 43, colCount: 7 });
    expect(sheet.cells).toContainEqual([41, 6, 'corner']);
  });

  it('rejects a non-integer row index in the path', async () => {
    const res = await request(appFor(freshDb())).delete(
      `/api/workbooks/${SEED_WORKBOOK_ID}/worksheets/${SEED_SHEET1_ID}/rows/abc`,
    );
    expect(res.status).toBe(400);
  });
});

