  patchWorksheet(
    workbookId: string,
    worksheetId: string,
    patch: { name?: string; isActive?: boolean },
  ): Promise<WorkbookSnapshot> {
    return request<WorkbookSnapshot>(worksheetPath(workbookId, worksheetId), {
      method: 'PATCH',
      body: JSON.stringify(patch),
    });
  },
  /** Add a blank worksheet (REQ-2-1-1). Answers with the full workbook snapshot. */
  createWorksheet(workbookId: string, name?: string): Promise<WorkbookSnapshot> {
    return request<WorkbookSnapshot>(`/api/workbooks/${encodeURIComponent(workbookId)}/worksheets`, {
      method: 'POST',
      body: JSON.stringify(name === undefined ? {} : { name }),
    });
  },
  /** Delete a worksheet and activate an adjacent one (REQ-2-1-4). */
  deleteWorksheet(workbookId: string, worksheetId: string): Promise<WorkbookSnapshot> {
    return request<WorkbookSnapshot>(worksheetPath(workbookId, worksheetId), { method: 'DELETE' });
  },
  /** Insert `count` rows above/below the target row (REQ-2-2-1). */
  insertRows(
    workbookId: string,
    worksheetId: string,
    requestBody: StructureInsertRequest,
  ): Promise<WorkbookSnapshot> {
    return request<WorkbookSnapshot>(`${worksheetPath(workbookId, worksheetId)}/rows`, {
      method: 'POST',
      body: JSON.stringify(requestBody),
    });
  },
