import { useEffect, useRef, type CSSProperties } from 'react';

export interface MenuEntry {
  label: string;
  onSelect: () => void;
}

export interface MenuProps {
  label: string;
  items: (MenuEntry | 'separator')[];
  onClose: () => void;
  className?: string;
  style?: CSSProperties;
}

export function Menu({ label, items, onClose, className, style }: MenuProps) {
  const ref = useRef<HTMLDivElement>(null);
  useEffect(() => {
    const onKeyDown = (e: KeyboardEvent) => { if (e.key === 'Escape') onClose(); };
    const onPointerDown = (e: MouseEvent) => {
      if (ref.current && !ref.current.contains(e.target as Node)) onClose();
    };
    const onScroll = () => onClose();
    window.addEventListener('keydown', onKeyDown);
    window.addEventListener('mousedown', onPointerDown, true);
    window.addEventListener('scroll', onScroll, true);
    return () => {...};
  }, [onClose]);
  return (
    <div ref={ref} role="menu" aria-label={label} className={...} style={style}>
      {items.map((item, i) => item === 'separator'
        ? <div key={`sep-${i}`} role="separator" className="my-1 border-t-1 border-sheet-border" />
        : <button key={item.label} type="button" role="menuitem" onClick={() => { onClose(); item.onSelect(); }} className="...">{item.label}</button>)}
    </div>
  );
}
```

