import { expect, test, type APIRequestContext, type Page } from '@playwright/test';

/**
 * Sub-issue B acceptance (Issue #4 REQ-2-1-1…2-2-2): worksheet lifecycle and
 * row/column structure driven through the visible controls only, locating
 * everything by accessible name (`exact: true` / `[aria-label]` per contract
 * v1.2).
 *
 * Isolation: every mutating test creates its own workbook through the API and
 * opens `/workbook/<id>`, so the seeded `Q3 Sales` structure that the smoke
 * suite asserts stays untouched (the one seed-based naming test restores it).
 * Formula-reference rewriting (C, #5) and the validation/pivot entry points
 * (E, #7) are not delivered yet; those assertions are marked where they belong.
 */

interface WorksheetSnapshot {
  id: string;
  name: string;
  position: number;
  isActive: boolean;
  rowCount: number;
  colCount: number;
  cells: [number, number, string][];
}

interface WorkbookSnapshot {
  id: string;
  name: string;
  worksheets: WorksheetSnapshot[];
}

async function createWorkbook(request: APIRequestContext, name: string): Promise<WorkbookSnapshot> {
  const res = await request.post('/api/workbooks', { data: { name } });
  expect(res.ok()).toBeTruthy();
  return (await res.json()) as WorkbookSnapshot;
}

async function putCells(
  request: APIRequestContext,
  workbookId: string,
  worksheetId: string,
  changes: { row: number; col: number; raw: string }[],
): Promise<void> {
  const res = await request.put(`/api/workbooks/${workbookId}/worksheets/${worksheetId}/cells`, {
    data: { changes },
  });
  expect(res.ok()).toBeTruthy();
}

async function openWorkbook(page: Page, workbookId: string): Promise<void> {
  await page.goto(`/workbook/${workbookId}`);
  await expect(page.getByRole('grid', { name: 'Worksheet grid' })).toBeVisible();
}

async function openTabOptions(page: Page, worksheetName: string): Promise<void> {
  await page.getByRole('button', { name: `Worksheet options for ${worksheetName}` }).click();
}

test.describe('worksheet lifecycle', () => {
  test('adds a worksheet named SheetN, activates it with A1 selected and keeps it after refresh', async ({
    page,
    request,
  }) => {
    const workbook = await createWorkbook(request, 'Add Worksheet Test');
    await openWorkbook(page, workbook.id);

    await expect(page.getByRole('tab', { name: 'Sheet1', exact: true })).toHaveCount(1);
    await page.getByRole('button', { name: 'Add worksheet' }).click();

    // Only Sheet1 exists, so the first unused SheetN is Sheet2.
    const sheet2 = page.getByRole('tab', { name: 'Sheet2', exact: true });
    await expect(sheet2).toBeVisible();
    await expect(sheet2).toHaveAttribute('aria-selected', 'true');
    await expect(page.getByRole('tab', { name: 'Sheet1', exact: true })).toHaveAttribute(
      'aria-selected',
      'false',
    );
    // Blank and A1 selected.
    await expect(page.getByRole('gridcell', { name: 'A1', exact: true })).toHaveAttribute(
      'aria-selected',
      'true',
    );
    await expect(page.getByRole('gridcell', { name: 'A1', exact: true })).toBeEmpty();
    await expect(page.getByRole('rowheader')).toHaveCount(6);

    // Adding again continues the positive-integer sequence.
    await page.getByRole('button', { name: 'Add worksheet' }).click();
    await expect(page.getByRole('tab', { name: 'Sheet3', exact: true })).toBeVisible();

    await page.reload();
    await expect(page.getByRole('grid', { name: 'Worksheet grid' })).toBeVisible();
    await expect(page.getByRole('tab', { name: 'Sheet3', exact: true })).toHaveAttribute(
      'aria-selected',
      'true',
    );
  });

  test('adds Sheet3 to the seeded Sheet1+Sheet2 workbook and restores the seed', async ({
    page,
    request,
  }) => {
    const list = (await (await request.get('/api/workbooks')).json()) as {
      id: string;
      name: string;
    }[];
    const seed = list.find((entry) => entry.name === 'Q3 Sales');
    expect(seed).toBeTruthy();
    const seedId = seed?.id ?? '';

    try {
      await openWorkbook(page, seedId);
      await page.getByRole('button', { name: 'Add worksheet' }).click();
      await expect(page.getByRole('tab', { name: 'Sheet3', exact: true })).toHaveAttribute(
        'aria-selected',
        'true',
      );
      await page.reload();
      await expect(page.getByRole('tab', { name: 'Sheet3', exact: true })).toBeVisible();
    } finally {
      // Restore the seed workbook to Sheet1+Sheet2 with Sheet1 active so the
      // smoke suite's exact structure assertions hold in any run order.
      const snapshot = (await (
        await request.get(`/api/workbooks/${seedId}`)
      ).json()) as WorkbookSnapshot;
      for (const worksheet of snapshot.worksheets.slice(2)) {
        await request.delete(`/api/workbooks/${seedId}/worksheets/${worksheet.id}`);
      }
      const restored = (await (
        await request.get(`/api/workbooks/${seedId}`)
      ).json()) as WorkbookSnapshot;
      const sheet1 = restored.worksheets.find((worksheet) => worksheet.name === 'Sheet1');
      if (sheet1 && !sheet1.isActive) {
        await request.patch(`/api/workbooks/${seedId}/worksheets/${sheet1.id}`, {
          data: { isActive: true },
        });
      }
    }
  });

  test('switching restores each worksheet state and reopening keeps the last active tab', async ({
    page,
    request,
  }) => {
    const workbook = await createWorkbook(request, 'Switch Worksheet Test');
    const sheet1 = workbook.worksheets[0];
    await putCells(request, workbook.id, sheet1.id, [
      { row: 0, col: 0, raw: 'one' },
      { row: 1, col: 1, raw: '42' },
    ]);
    await openWorkbook(page, workbook.id);

    // Confirm a selection on Sheet1; it must be restored when returning.
    await page.getByRole('gridcell', { name: 'B2', exact: true }).click();
    await expect(page.getByRole('gridcell', { name: 'B2', exact: true })).toHaveAttribute(
      'aria-selected',
      'true',
    );

    await page.getByRole('button', { name: 'Add worksheet' }).click();
    await expect(page.getByRole('tab', { name: 'Sheet2', exact: true })).toHaveAttribute(
      'aria-selected',
      'true',
    );
    // The new worksheet is genuinely separate: A1 empty, formula bar empty.
    const formulaBar = page.getByRole('textbox', { name: 'Formula bar' });
    await expect(formulaBar).toHaveValue('');
    await page.getByRole('gridcell', { name: 'A1', exact: true }).dblclick();
    const editor = page.getByRole('textbox', { name: 'Edit A1' });
    await editor.fill('two');
    await editor.press('Enter');
    await expect(formulaBar).toHaveValue('two');

    // Back to Sheet1: grid, selection and formula bar switch to its state.
    await page.getByRole('tab', { name: 'Sheet1', exact: true }).click();
    await expect(page.getByRole('gridcell', { name: 'A1', exact: true })).toHaveText('one');
    await expect(page.getByRole('gridcell', { name: 'B2', exact: true })).toHaveAttribute(
      'aria-selected',
      'true',
    );
    await expect(formulaBar).toHaveValue('42');

    // Sheet2 is the last active tab and keeps its own selection.
    await page.reload();
    await expect(page.getByRole('tab', { name: 'Sheet2', exact: true })).toHaveAttribute(
      'aria-selected',
      'true',
    );
    await expect(page.getByRole('gridcell', { name: 'A1', exact: true })).toHaveText('two');
    await expect(page.getByRole('gridcell', { name: 'A1', exact: true })).toHaveAttribute(
      'aria-selected',
      'true',
    );
  });

  test('renames through the tab menu, persists, and shows the exact empty/duplicate messages', async ({
    page,
    request,
  }) => {
    const workbook = await createWorkbook(request, 'Rename Worksheet Test');
    await openWorkbook(page, workbook.id);

    await openTabOptions(page, 'Sheet1');
    await page.getByRole('menuitem', { name: 'Rename' }).click();
    const dialog = page.getByRole('dialog', { name: 'Rename worksheet' });
    await expect(dialog).toBeVisible();
    const nameInput = dialog.getByRole('textbox', { name: 'Worksheet name' });
    await expect(nameInput).toHaveValue('Sheet1');
    await nameInput.fill('  Budget  ');
    await dialog.getByRole('button', { name: 'Save' }).click();
    await expect(page.getByRole('tab', { name: 'Budget', exact: true })).toBeVisible();

    // Empty name: exact message, dialog stays, original name remains.
    await openTabOptions(page, 'Budget');
    await page.getByRole('menuitem', { name: 'Rename' }).click();
    await dialog.getByRole('textbox', { name: 'Worksheet name' }).fill('   ');
    await dialog.getByRole('button', { name: 'Save' }).click();
    await expect(dialog.getByText('Worksheet name cannot be empty')).toBeVisible();
    await dialog.getByRole('button', { name: 'Cancel' }).click();
    await expect(page.getByRole('tab', { name: 'Budget', exact: true })).toBeVisible();

    // Duplicate name against another worksheet.
    await page.getByRole('button', { name: 'Add worksheet' }).click();
    await expect(page.getByRole('tab', { name: 'Sheet2', exact: true })).toBeVisible();
    await openTabOptions(page, 'Sheet2');
    await page.getByRole('menuitem', { name: 'Rename' }).click();
    await dialog.getByRole('textbox', { name: 'Worksheet name' }).fill('Budget');
    await dialog.getByRole('button', { name: 'Save' }).click();
    await expect(dialog.getByText('Worksheet name already exists')).toBeVisible();
    await dialog.getByRole('button', { name: 'Cancel' }).click();

    await page.reload();
    await expect(page.getByRole('tab', { name: 'Budget', exact: true })).toBeVisible();
    await expect(page.getByRole('tab', { name: 'Sheet2', exact: true })).toBeVisible();
  });

  test('deletes through the named dialog, activates the neighbour and removes the data', async ({
    page,
    request,
  }) => {
    const workbook = await createWorkbook(request, 'Delete Worksheet Test');
    const sheet1 = workbook.worksheets[0];
    await putCells(request, workbook.id, sheet1.id, [{ row: 0, col: 0, raw: 'keep' }]);
    await openWorkbook(page, workbook.id);

    await page.getByRole('button', { name: 'Add worksheet' }).click();
    await expect(page.getByRole('tab', { name: 'Sheet2', exact: true })).toHaveAttribute(
      'aria-selected',
      'true',
    );
    await page.getByRole('gridcell', { name: 'A1', exact: true }).dblclick();
    await page.getByRole('textbox', { name: 'Edit A1' }).fill('doomed');
    await page.getByRole('textbox', { name: 'Edit A1' }).press('Enter');

    await openTabOptions(page, 'Sheet2');
    await page.getByRole('menuitem', { name: 'Delete' }).click();
    const dialog = page.getByRole('dialog', { name: 'Delete worksheet' });
    await expect(dialog).toBeVisible();
    // The dialog describes the target worksheet by name.
    await expect(dialog.getByText(/Sheet2/)).toBeVisible();
    await dialog.getByRole('button', { name: 'Delete worksheet' }).click();

    await expect(page.getByRole('tab', { name: 'Sheet2', exact: true })).toHaveCount(0);
    // The deleted tab was active; the remaining neighbour becomes active.
    await expect(page.getByRole('tab', { name: 'Sheet1', exact: true })).toHaveAttribute(
      'aria-selected',
      'true',
    );
    await expect(page.getByRole('gridcell', { name: 'A1', exact: true })).toHaveText('keep');

    await page.reload();
    await expect(page.getByRole('tab', { name: 'Sheet2', exact: true })).toHaveCount(0);
  });

  test('refuses to delete the last worksheet without opening a dialog', async ({ page, request }) => {
    const workbook = await createWorkbook(request, 'Last Worksheet Test');
    await openWorkbook(page, workbook.id);

    await openTabOptions(page, 'Sheet1');
    await page.getByRole('menuitem', { name: 'Delete' }).click();
    await expect(page.getByRole('dialog')).toHaveCount(0);
    await expect(
      page.getByText('A workbook must contain at least one worksheet'),
    ).toBeVisible();
    await expect(page.getByRole('tab', { name: 'Sheet1', exact: true })).toHaveAttribute(
      'aria-selected',
      'true',
    );
  });
});

test.describe('row and column structure', () => {
  test('row header menu inserts rows, shifts data, persists and leaves other worksheets alone', async ({
    page,
    request,
  }) => {
    const workbook = await createWorkbook(request, 'Row Structure Test');
    const sheet1 = workbook.worksheets[0];
    await putCells(request, workbook.id, sheet1.id, [
      { row: 0, col: 0, raw: 'Region' },
      { row: 1, col: 0, raw: 'East' },
      { row: 2, col: 0, raw: 'North' },
    ]);
    const added = await request.post(`/api/workbooks/${workbook.id}/worksheets`, {
      data: { name: 'Other' },
    });
    expect(added.ok()).toBeTruthy();
    await openWorkbook(page, workbook.id);
    await page.getByRole('tab', { name: 'Sheet1', exact: true }).click();

    // Right-click opens the menu; commands are ARIA menuitems.
    const rowTwo = page.getByRole('rowheader', { name: '2', exact: true });
    await rowTwo.click({ button: 'right' });
    const menu = page.getByRole('menu');
    await expect(menu).toBeVisible();
    await expect(page.getByRole('menuitem', { name: 'Insert 1 row above' })).toBeVisible();
    await expect(page.getByRole('menuitem', { name: 'Insert 1 row below' })).toBeVisible();
    await expect(page.getByRole('menuitem', { name: 'Delete row' })).toBeVisible();

    await page.getByRole('menuitem', { name: 'Insert 1 row above' }).click();
    await expect(page.getByRole('rowheader')).toHaveCount(7);
    // Row 1 keeps its value; the old row 2 data moved down to row 3.
    await expect(page.getByRole('gridcell', { name: 'A1', exact: true })).toHaveText('Region');
    await expect(page.getByRole('gridcell', { name: 'A2', exact: true })).toBeEmpty();
    await expect(page.getByRole('gridcell', { name: 'A3', exact: true })).toHaveText('East');
    await expect(page.getByRole('gridcell', { name: 'A4', exact: true })).toHaveText('North');

    await page.reload();
    await expect(page.getByRole('rowheader')).toHaveCount(7);
    await expect(page.getByRole('gridcell', { name: 'A3', exact: true })).toHaveText('East');

    // Deleting the inserted row moves the following data back up.
    await page.getByRole('rowheader', { name: '2', exact: true }).click({ button: 'right' });
    await page.getByRole('menuitem', { name: 'Delete row' }).click();
    await expect(page.getByRole('rowheader')).toHaveCount(6);
    await expect(page.getByRole('gridcell', { name: 'A2', exact: true })).toHaveText('East');

    // The other worksheet keeps its own structure.
    await page.getByRole('tab', { name: 'Other', exact: true }).click();
    await expect(page.getByRole('rowheader')).toHaveCount(6);
  });

  test('column header menu inserts and deletes columns symmetrically', async ({ page, request }) => {
    const workbook = await createWorkbook(request, 'Column Structure Test');
    const sheet1 = workbook.worksheets[0];
    await putCells(request, workbook.id, sheet1.id, [
      { row: 0, col: 0, raw: 'Region' },
      { row: 0, col: 1, raw: 'Sales' },
      { row: 0, col: 2, raw: 'Status' },
